/* DAWAH X — ahmad, অধ্যায় 99 · খণ্ড 99 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][99]=[[19601,19601,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ نَفْسًا ‏ ‏مُعَاهَدَةً ‏ ‏بِغَيْرِ حَقِّهَا لَمْ يَجِدْ رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ خَمْسِ مِائَةِ عَامٍ ‏","","",""],[19602,19602,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَرِدَنَّ الْحَوْضَ عَلَيَّ رِجَالٌ مِمَّنْ صَحِبَنِي وَرَآنِي فَإِذَا رُفِعُوا إِلَيَّ وَرَأَيْتُهُمْ ‏ ‏اخْتُلِجُوا ‏ ‏دُونِي فَلَأَقُولَنَّ أُصَيْحَابِي أُصَيْحَابِي فَيُقَالُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[19603,19603,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ يَلِي ‏ ‏أَمْرَ ‏ ‏فَارِسَ ‏ ‏قَالُوا امْرَأَةٌ قَالَ ‏ ‏مَا أَفْلَحَ قَوْمٌ يَلِي ‏ ‏أَمْرَهُمْ ‏ ‏امْرَأَةٌ ‏","","",""],[19604,19604,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏جِئْتُ وَنَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَاكِعٌ قَدْ حَفَزَنِي النَّفَسُ فَرَكَعْتُ دُونَ الصَّفِّ فَلَمَّا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ قَالَ ‏ ‏أَيُّكُمْ رَكَعَ دُونَ الصَّفِّ قُلْتُ أَنَا قَالَ زَادَكَ اللَّهُ حِرْصًا وَلَا تَعُدْ ‏","","",""],[19605,19605,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرَأَيْتُمْ إِنْ كَانَ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏خَيْرًا مِنْ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏أَتَرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ فَإِنَّهُمْ خَيْرٌ مِنْهُمْ ثُمَّ قَالَ أَرَأَيْتُمْ إِنْ كَانَتْ ‏ ‏جُهَيْنَةُ ‏ ‏وَمُزَيْنَةُ ‏ ‏خَيْرًا مِنْ الْحَلِيفَيْنِ مِنْ ‏ ‏تَمِيمٍ ‏ ‏وَعَامِرِ بْنِ صَعْصَعَةَ ‏ ‏يَمُدُّ بِهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَوْتَهُ أَتَرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ فَإِنَّهُمْ خَيْرٌ مِنْهُمْ ‏","","",""],[19606,19606,"","","‏ ‏قَالَ وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرَا عِيدٍ لَا يَنْقُصَانِ رَمَضَانُ وَذُو الْحِجَّةِ ‏","","",""],[19607,19607,"","","‏ ‏وَقَالَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏ذُكِرَ رَجُلٌ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَثْنَى عَلَيْهِ رَجُلٌ خَيْرًا فَقَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَكَ ‏ ‏قَطَعْتَ عُنُقَ أَخِيكَ وَاللَّهِ لَوْ سَمِعَهَا مَا أَفْلَحَ أَبَدًا ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَثْنَى أَحَدُكُمْ عَلَى أَحَدٍ فَلْيَقُلْ وَاللَّهِ إِنَّ فُلَانًا وَلَا أُزَكِّي عَلَى اللَّهِ أَحَدًا ‏","","",""],[19608,19608,"","","‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُحَمَّدٍ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَرَأَيْتُمْ إِنْ كَانَتْ ‏ ‏أَسْلَمُ ‏ ‏وَغِفَارُ ‏ ‏خَيْرًا مِنْ الْحَلِيفَيْنِ ‏ ‏أَسَدٍ ‏ ‏وَغَطَفَانَ ‏ ‏أَتَرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ أَفَرَأَيْتُمْ إِنْ كَانَتْ ‏ ‏مُزَيْنَةُ ‏ ‏وَجُهَيْنَةُ ‏ ‏خَيْرًا مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَعَامِرِ بْنِ صَعْصَعَةَ ‏ ‏وَرَفَعَ ‏ ‏حَمَّادٌ ‏ ‏بِهَا صَوْتَهُ يَحْكِي النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَرَوْنَهُمْ خَسِرُوا قَالُوا نَعَمْ قَالَ فَإِنَّهُمْ خَيْرٌ مِنْهُمْ ‏","","",""],[19609,19609,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ يَا ‏ ‏مُحَمَّدُ ‏ ‏اقْرَأْ الْقُرْآنَ عَلَى ‏ ‏حَرْفٍ ‏ ‏قَالَ ‏ ‏مِيكَائِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏اسْتَزِدْهُ فَاسْتَزَادَهُ قَالَ اقْرَأْهُ عَلَى ‏ ‏حَرْفَيْنِ ‏ ‏قَالَ ‏ ‏مِيكَائِيلُ ‏ ‏اسْتَزِدْهُ فَاسْتَزَادَهُ حَتَّى بَلَغَ سَبْعَةَ ‏ ‏أَحْرُفٍ ‏ ‏قَالَ كُلٌّ شَافٍ كَافٍ مَا لَمْ تَخْتِمْ آيَةَ عَذَابٍ بِرَحْمَةٍ أَوْ آيَةَ رَحْمَةٍ بِعَذَابٍ نَحْوَ قَوْلِكَ تَعَالَ وَأَقْبِلْ وَهَلُمَّ وَاذْهَبْ وَأَسْرِعْ وَاعْجَلْ ‏","","",""],[19610,19610,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ نَفْسًا ‏ ‏مُعَاهَدَةً ‏ ‏بِغَيْرِ حَقِّهَا لَمْ يَجِدْ رَائِحَةَ الْجَنَّةِ وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ مِائَةِ عَامٍ ‏","","",""],[19611,19611,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي فَإِذَا سَجَدَ ‏ ‏وَثَبَ ‏ ‏الْحَسَنُ ‏ ‏عَلَى ظَهْرِهِ وَعَلَى عُنُقِهِ فَيَرْفَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَفْعًا رَفِيقًا لِئَلَّا ‏ ‏يُصْرَعَ ‏ ‏قَالَ فَعَلَ ذَلِكَ غَيْرَ مَرَّةٍ فَلَمَّا قَضَى صَلَاتَهُ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏رَأَيْنَاكَ صَنَعْتَ ‏ ‏بالْحَسَنِ ‏ ‏شَيْئًا مَا رَأَيْنَاكَ صَنَعْتَهُ قَالَ إِنَّهُ رَيْحَانَتِي مِنْ الدُّنْيَا وَإِنَّ ابْنِي هَذَا سَيِّدٌ وَعَسَى اللَّهُ تَبَارَكَ وَتَعَالَى أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ مِنْ الْمُسْلِمِينَ ‏","","",""],[19612,19612,"","","‏ ‏وَبِهِ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَنْ يُفْلِحَ قَوْمٌ تَمْلِكُهُمْ امْرَأَةٌ ‏","","",""],[19613,19613,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا وَكِلَاهُمَا يُرِيدُ أَنْ يَقْتُلَ صَاحِبَهُ فَقَتَلَ أَحَدُهُمَا الْآخَرَ فَهُمَا فِي النَّارِ قِيلَ يَا رَسُولَ اللَّهِ هَذَا الْقَاتِلُ فَمَا بَالُ الْمَقْتُولِ قَالَ لِأَنَّهُ أَرَادَ قَتْلَ صَاحِبِهِ ‏","","",""],[19614,19614,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏وَيُونُسُ ‏ ‏وَهِشَامٌ ‏ ‏وَالْمُعَلَّي بْنُ زِيَادٍ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏الْأَحْنَفِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا تَوَاجَهَ الْمُسْلِمَانِ بِسَيْفَيْهِمَا فَقَتَلَ أَحَدُهُمَا صَاحِبَهُ فَهُمَا فِي النَّارِ جَمِيعًا ‏","","",""],[19615,19615,"","","‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏وَصَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ صِفَةَ ‏ ‏الدَّجَّالِ ‏ ‏وَصِفَةَ أَبَوَيْهِ قَالَ ‏ ‏يَمْكُثُ أَبَوَا ‏ ‏الدَّجَّالِ ‏ ‏ثَلَاثِينَ سَنَةً لَا يُولَدُ لَهُمَا ثُمَّ يُولَدُ لَهُمَا ابْنٌ مَسْرُورٌ ‏ ‏مَخْتُونٌ ‏ ‏أَقَلُّ ‏ ‏شَيْءٍ نَفْعًا وَأَضَرُّهُ تَنَامُ عَيْنَاهُ وَلَا يَنَامُ قَلْبُهُ ‏ ‏فَذَكَرَهُ ‏ ‏إِلَّا أَنَّهُ قَالَ ثُمَّ وُلِدَ لَنَا هَذَا أَعْوَرَ مَسْرُورًا ‏ ‏مَخْتُونًا ‏ ‏أَقَلَّ شَيْءٍ نَفْعًا وَأَضَرَّهُ ‏","","",""],[19616,19616,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏أَبِي بَكْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَقُولَنَّ أَحَدُكُمْ إِنِّي قُمْتُ رَمَضَانَ كُلَّهُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَاللَّهُ أَعْلَمُ ‏ ‏أَخَشِيَ التَّزْكِيَةَ عَلَى أُمَّتِهِ أَوْ يَقُولُ لَا بُدَّ مِنْ رَاقِدٍ أَوْ غَافِلٍ ‏","","",""],[19617,19617,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَن ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏كَتَبَ ‏ ‏أَبُو بَكْرَةَ ‏ ‏إِلَى ابْنِهِ وَهُوَ عَامِلٌ ‏ ‏بِسِجِسْتَانَ ‏ ‏أَنْ لَا تَقْضِيَ بَيْنَ رَجُلَيْنِ وَأَنْتَ غَضْبَانُ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَقْضِ حَكَمٌ بَيْنَ اثْنَيْنِ ‏ ‏أَوْ خَصْمَيْنِ ‏ ‏وَهُوَ غَضْبَانُ ‏","","",""],[19618,19618,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَن ‏ ‏يُونُسَ بْنِ عُبَيْدٍ ‏ ‏عَن ‏ ‏الْحَكَمِ بْنِ الْأَعْرَجِ ‏ ‏عَن ‏ ‏الْأَشْعَثِ بْنِ ثُرْمُلَةَ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ نَفْسًا ‏ ‏مُعَاهَدَةً ‏ ‏بِغَيْرِ حَقِّهَا فَقَدْ حَرَّمَ اللَّهُ تَبَارَكَ وَتَعَالَى عَلَيْهِ الْجَنَّةَ أَنْ يَشُمَّ رِيحَهَا ‏","","",""],[19619,19619,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ بْنُ عَبْدِ الْمَجِيدِ الثَّقَفِيُّ ‏ ‏عَن ‏ ‏أَيُّوبَ ‏ ‏عَن ‏ ‏مُحَمَّدٍ ‏ ‏فَذَكَرَ قِصَّةً فِيهَا ‏ ‏قَالَ ‏ ‏فَلَمَّا قَدِمَ ‏ ‏خُيِّرَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏بَيْنَ ثَلَاثِينَ أَلْفًا وَبَيْنَ آنِيَةٍ مِنْ فِضَّةٍ قَالَ فَاخْتَارَ الْآنِيَةَ قَالَ فَقَدِمَ تُجَّارٌ مِنْ ‏ ‏دَارِينَ ‏ ‏فَبَاعَهُمْ إِيَّاهَا الْعَشْرَةَ ثَلَاثَةَ عَشْرَةَ ثُمَّ لَقِيَ ‏ ‏أَبَا بَكْرَةَ ‏ ‏فَقَالَ أَلَمْ تَرَ كَيْفَ خَدَعْتُهُمْ قَالَ كَيْفَ فَذَكَرَ لَهُ ذَلِكَ قَالَ ‏ ‏عَزَمْتُ ‏ ‏عَلَيْكَ ‏ ‏أَوْ أَقْسَمْتُ عَلَيْكَ ‏ ‏لَتَرُدَّنَّهَا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ مِثْلِ هَذَا ‏","","",""],[19620,19620,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَابْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏وَأَبُو عَاصِمٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏إِسْمَاعِيلُ بْنُ مُحَمَّدِ بْنِ سَعِيدٍ ‏ ‏أَنَّهُ أَخْبَرَهُ ‏ ‏حُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ ‏ ‏أَنَّ ‏ ‏السَّائِبَ بْنَ يَزِيدَ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏الْعَلَاءَ بْنَ الْحَضْرَمِيِّ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَمْكُثُ الْمُهَاجِرُ ‏ ‏بِمَكَّةَ ‏ ‏بَعْدَ قَضَاءِ ‏ ‏نُسُكِهِ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ‏ ‏أَبُو عَاصِمٍ ‏ ‏ثَلَاثَ لَيَالٍ ‏","","",""],[19621,19621,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ حُمَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُمَرَ بْنَ عَبْدِ الْعَزِيزِ ‏ ‏يَسْأَلُ ‏ ‏السَّائِبَ ‏ ‏مَا سَمِعْتَ فِي السُّكْنَى ‏ ‏بِمَكَّةَ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏الْعَلَاءُ بْنُ الْحَضْرَمِيِّ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِلْمُهَاجِرِ ثَلَاثًا بَعْدَ ‏ ‏الصَّدَرِ ‏","","",""],[19622,19622,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَيَحْيَى بْنُ مَعِينٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو حَمْزَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُغِيرَةَ الْأَزْدِيَّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏حَيَّانَ الْأَعْرَجِ ‏ ‏عَنِ ‏ ‏الْعَلَاءِ بْنِ الْحَضْرَمِيِّ ‏ ‏قَالَ ‏ ‏بَعَثَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏الْبَحْرَيْنِ ‏ ‏أَوْ أَهْلِ ‏ ‏هَجَرَ ‏ ‏شَكَّ ‏ ‏أَبُو حَمْزَةَ ‏ ‏قَالَ ‏ ‏وَكُنْتُ آتِي ‏ ‏الْحَائِطَ ‏ ‏يَكُونُ بَيْنَ الْإِخْوَةِ فَيُسْلِمُ أَحَدُهُمْ فَآخُذُ مِنْ الْمُسْلِمِ الْعُشْرَ وَمِنْ الْآخَرِ ‏ ‏الْخَرَاجَ ‏","","",""],[19623,19623,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏قَالَ ‏ ‏كُنْتُ فِي مَجْلِسٍ فِيهِ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لِرَجُلٍ ‏ ‏مِنْ جُلَسَائِهِ كَيْفَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْإِسْلَامَ بَدَأَ ‏ ‏جَذَعًا ‏ ‏ثُمَّ ‏ ‏ثَنِيًّا ‏ ‏ثُمَّ ‏ ‏رَبَاعِيًا ‏ ‏ثُمَّ ‏ ‏سَدَاسِيًّا ثُمَّ بَازِلًا قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏فَمَا بَعْدَ الْبُزُولِ إِلَّا النُّقْصَانُ ‏","","",""],[19624,19624,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ اللَّيْثِيِّ ‏ ‏قَالَ ‏ ‏قَدِمْنَا عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَنَحْنُ شَبَبَةٌ قَالَ فَأَقَمْنَا عِنْدَهُ نَحْوًا مِنْ عِشْرِينَ لَيْلَةً فَقَالَ لَنَا لَوْ رَجَعْتُمْ إِلَى بِلَادِكُمْ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحِيمًا فَعَلَّمْتُمُوهُمْ ‏ ‏قَالَ ‏ ‏سُرَيْجٌ ‏ ‏وَأَمَرْتُمُوهُمْ أَنْ يُصَلُّوا صَلَاةَ كَذَا حِينَ كَذَا ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏وَمُرُوهُمْ فَلْيُصَلُّوا صَلَاةَ كَذَا فِي حِينِ كَذَا وَصَلَاةَ كَذَا فِي حِينِ كَذَا ‏ ‏فَإِذَا حَضَرَتْ الصَّلَاةُ فَلْيُؤَذِّنْ لَكُمْ أَحَدُكُمْ وَلْيَؤُمَّكُمْ أَكْبَرُكُمْ ‏","","",""],[19625,19625,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ وَهُوَ أَبُو سُلَيْمَانَ ‏ ‏أَنَّهُمْ أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ وَصَاحِبٌ لَهُ ‏ ‏أَوْ صَاحِبَانِ لَهُ فَقَالَ أَحَدُهُمَا صَاحِبَيْنِ لَهُ ‏ ‏أَيُّوبُ ‏ ‏أَوْ ‏ ‏خَالِدٌ ‏ ‏فَقَالَ لَهُمَا ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ فَأَذِّنَا وَأَقِيمَا وَلْيَؤُمَّكُمَا أَكْبَرُكُمَا وَصَلُّوا كَمَا تَرَوْنِي أُصَلِّي ‏","","",""],[19626,19626,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏وَكَانَ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُ يَدَيْهِ إِذَا دَخَلَ فِي الصَّلَاةِ وَإِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ إِلَى أُذُنَيْهِ ‏","","",""],[19627,19627,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏بُدَيْلِ بْنِ مَيْسَرَةَ الْعُقَيْلِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْهُمْ ‏ ‏يُكَنَّى ‏ ‏أَبَا عَطِيَّةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ ‏ ‏يَأْتِينَا فِي مُصَلَّانَا يَتَحَدَّثُ قَالَ فَحَضَرَتْ الصَّلَاةُ يَوْمًا فَقُلْنَا تَقَدَّمْ فَقَالَ لَا لِيَتَقَدَّمْ بَعْضُكُمْ حَتَّى أُحَدِّثَكُمْ لِمَ لَا أَتَقَدَّمُ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مَنْ زَارَ قَوْمًا فَلَا يَؤُمَّهُمْ وَلْيَؤُمَّهُمْ رَجُلٌ مِنْهُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏حَدَّثَنَاه ‏ ‏إِبْرَاهِيمُ بْنُ الْحَجَّاجِ ‏ ‏وَمُحَمَّدُ بْنُ أَبَانَ الْوَاسِطِيُّ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏بُدَيْلٌ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ الْعَطَّارُ ‏ ‏عَنْ ‏ ‏بُدَيْلِ بْنِ مَيْسَرَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عَطِيَّةَ ‏ ‏مَوْلًى لَنَا قَالَ كَانَ ‏ ‏مَالِكُ بْنُ الْحُوَيْرِثِ ‏ ‏يَأْتِينَا فِي مُصَلَّانَا ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ أَبِي ‏","","",""],[19628,19628,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَأَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا كَبَّرَ رَفَعَ يَدَيْهِ حَتَّى يَجْعَلَهُمَا قَرِيبًا مِنْ أُذُنَيْهِ وَإِذَا رَكَعَ صَنَعَ مِثْلَ ذَلِكَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[19629,19629,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ فِي الصَّلَاةِ رَفَعَ يَدَيْهِ وَإِذَا رَكَعَ وَإِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ حَتَّى حَاذَتَا فُرُوعَ أُذُنَيْهِ ‏","","",""],[19630,19630,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏نَصْرِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَرْفَعُ يَدَيْهِ ‏ ‏حِيَالَ ‏ ‏فُرُوعِ أُذُنَيْهِ فِي الرُّكُوعِ وَالسُّجُودِ ‏","","",""],[19631,19631,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏بُدَيْلُ بْنُ مَيْسَرَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَطِيَّةَ ‏ ‏مَوْلًى مِنَّا ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ ‏ ‏قَالَ ‏ ‏كَانَ يَأْتِينَا فِي مُصَلَّانَا فَلَمَّا أُقِيمَتْ الصَّلَاةُ قِيلَ لَهُ تَقَدَّمْ ‏ ‏فَصَلِّهْ قَالَ لِيُصَلِّ بَعْضُكُمْ حَتَّى أُحَدِّثَكُمْ لِمَ لَا أُصَلِّي بِكُمْ فَلَمَّا صَلَّى الْقَوْمُ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا زَارَ أَحَدُكُمْ قَوْمًا فَلَا يُصَلِّيَنَّ بِهِمْ ‏ ‏يُصَلِّي بِهِمْ رَجُلٌ مِنْهُمْ ‏","","",""],[19632,19632,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ الْحُوَيْرِثِ اللَّيْثِيِّ ‏ ‏أَنَّهُ ‏ ‏قَالَ لِأَصْحَابِهِ يَوْمًا أَلَا ‏ ‏أُرِيكُمْ كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ وَذَلِكَ فِي غَيْرِ حِينِ صَلَاةٍ ‏ ‏فَقَامَ فَأَمْكَنَ الْقِيَامَ ثُمَّ رَكَعَ فَأَمْكَنَ الرُّكُوعَ ثُمَّ رَفَعَ رَأْسَهُ وَانْتَصَبَ قَائِمًا هُنَيَّةً ثُمَّ سَجَدَ ثُمَّ رَفَعَ رَأْسَهُ وَيُكَبِّرُ فِي الْجُلُوسِ ثُمَّ انْتَظَرَ هُنَيَّةً ثُمَّ سَجَدَ ‏ ‏قَالَ ‏ ‏أَبُو قِلَابَةَ ‏ ‏فَصَلَّى صَلَاةً ‏ ‏كَصَلَاةِ شَيْخِنَا هَذَا ‏ ‏يَعْنِي ‏ ‏عَمْرَو بْنَ سَلِمَةَ الْجَرْمِيَّ ‏ ‏وَكَانَ يَؤُمُّ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏فَرَأَيْتُ ‏ ‏عَمْرَو بْنَ سَلِمَةَ ‏ ‏يَصْنَعُ شَيْئًا لَا أَرَاكُمْ تَصْنَعُونَهُ كَانَ ‏ ‏إِذَا رَفَعَ رَأْسَهُ مِنْ السَّجْدَتَيْنِ ‏ ‏اسْتَوَى ‏ ‏قَاعِدًا ثُمَّ قَامَ مِنْ الرَّكْعَةِ الْأُولَى وَالثَّانِيَةِ ‏","","",""],[19633,19633,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ صُهْبَانَ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْخَذْفِ ‏ ‏وَقَالَ إِنَّهُ لَا ‏ ‏يَنْكَأُ ‏ ‏عَدُوًّا وَلَا يَصِيدُ وَلَكِنَّهُ يَكْسِرُ ‏ ‏السِّنَّ ‏ ‏وَيَفْقَأُ الْعَيْنَ ‏","","",""],[19634,19634,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ الْعَلَاءِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حَضَرَتْ الصَّلَاةُ وَأَنْتُمْ فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ فَصَلُّوا وَإِذَا حَضَرَتْ وَأَنْتُمْ فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ فَلَا تُصَلُّوا فَإِنَّهَا خُلِقَتْ مِنْ الشَّيَاطِينِ ‏","","",""],[19635,19635,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏يَقُولُ ‏ ‏قَرَأَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ الْفَتْحِ فِي مَسِيرِهِ سُورَةَ ‏ ‏الْفَتْحِ ‏ ‏عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً نَزَلَتْ سُورَةُ ‏ ‏الْفَتْحِ ‏ ‏وَهُوَ فِي مَسِيرٍ لَهُ فَجَعَلَ يَقْرَأُ وَهُوَ عَلَى ‏ ‏رَاحِلَتِهِ ‏ ‏قَالَ فَرَجَّعَ فِيهَا ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَوْلَا أَنْ أَكْرَهَ أَنْ يَجْتَمِعَ النَّاسُ عَلَيَّ لَحَكَيْتُ لَكُمْ قِرَاءَتَهُ ‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏وَأَبُو طَالِبِ بْنُ جَابَانَ الْقَارِيُّ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَ هَذَا الْحَدِيثِ قَالَ ‏ ‏ابْنُ جَابَانَ ‏ ‏فِي حَدِيثِهِ آ آ ‏","","",""],[19636,19636,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا ثَنَا ‏ ‏كَهْمَسُ بْنُ الْحَسَنِ ‏ ‏عَنِ ‏ ‏ابْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ ثَلَاثَ مَرَّاتٍ لِمَنْ شَاءَ ‏","","",""],[19637,19637,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُثْمَانَ بْنِ غِيَاثٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو نَعَامَةَ ‏ ‏عَنِ ‏ ‏ابْنِ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُونَا ‏ ‏إِذَا سَمِعَ أَحَدًا مِنَّا يَقُولُ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ يَقُولُ ‏ ‏إِهِي ‏ ‏إِهِي ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏فَلَمْ أَسْمَعْ أَحَدًا مِنْهُمْ يَقُولُ بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏","","",""],[19638,19638,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِي جَعْفَرٍ الرَّازِيِّ ‏ ‏عَنِ ‏ ‏الرَّبِيعِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏غَيْرِهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏وَكَانَ أَحَدَ ‏ ‏الرَّهْطِ ‏ ‏الَّذِينَ نَزَلَتْ فِيهِمْ هَذِهِ الْآيَةُ ‏ { ‏وَلَا عَلَى الَّذِينَ إِذَا مَا أَتَوْكَ لِتَحْمِلَهُمْ ‏} ‏إِلَى آخِرِ الْآيَةِ ‏ ‏قَالَ ‏ ‏إِنِّي لَآخِذٌ بِغُصْنٍ مِنْ أَغْصَانِ الشَّجَرَةِ أُظِلُّ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ يُبَايِعُونَهُ فَقَالُوا ‏ ‏نُبَايِعُكَ عَلَى الْمَوْتِ قَالَ لَا وَلَكِنْ لَا تَفِرُّوا ‏","","",""],[19639,19639,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُفْيَانَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا فَاقْتُلُوا مِنْهَا كُلَّ أَسْوَدَ ‏ ‏بَهِيمٍ ‏","","",""],[19640,19640,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏أَبِي سُفْيَانَ بْنِ الْعَلَاءِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا فَاقْتُلُوا مِنْهَا كُلَّ أَسْوَدَ ‏ ‏بَهِيمٍ ‏ ‏قَالَ فَقَالَ لَهُ رَجُلٌ يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏مِمَّنْ سَمِعْتَ هَذَا قَالَ فَقَالَ حَدَّثَنِيهِ وَحَلَفَ ‏ ‏عَبْدُ اللَّهِ بْنُ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنْذُ كَذَا وَكَذَا وَلَقَدْ حَدَّثَنَا فِي ذَلِكَ الْمَجْلِسِ ‏","","",""],[19641,19641,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ أَبِي رَائِطَةَ الْحَذَّاءُ التَّمِيمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ زِيَادٍ ‏ ‏أَوْ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهَ اللَّهَ فِي أَصْحَابِي اللَّهَ اللَّهَ فِي أَصْحَابِي لَا تَتَّخِذُوهُمْ ‏ ‏غَرَضًا ‏ ‏بَعْدِي فَمَنْ أَحَبَّهُمْ فَبِحُبِّي أَحَبَّهُمْ ‏ ‏وَمَنْ أَبْغَضَهُمْ فَبِبُغْضِي أَبْغَضَهُمْ وَمَنْ آذَاهُمْ فَقَدْ آذَانِي وَمَنْ آذَانِي فَقَدْ آذَى اللَّهَ تَبَارَكَ وَتَعَالَى وَمَنْ آذَى اللَّهَ فَيُوشِكُ أَنْ يَأْخُذَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَوْنٍ الْخَرَّازُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عَبِيدَةَ بْنِ أَبِي رَائِطَةَ ‏ ‏بِمِثْلِ هَذَا الْحَدِيثِ ‏","","",""],[19642,19642,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ قَرِيبًا ‏ ‏لِعَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏خَذَفَ ‏ ‏فَنَهَاهُ وَقَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْخَذْفِ ‏ ‏وَقَالَ إِنَّهَا لَا تَصِيدُ صَيْدًا وَلَا ‏ ‏تَنْكَأُ ‏ ‏عَدُوًّا وَلَكِنَّهَا تَكْسِرُ ‏ ‏السِّنَّ ‏ ‏وَتَفْقَأُ الْعَيْنَ ‏ ‏قَالَ ‏ ‏فَعَادَ فَقَالَ حَدَّثْتُكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْهَا ثُمَّ عُدْتَ لَا أُكَلِّمُكَ أَبَدًا ‏","","",""],[19643,19643,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏وَحَدَّثَنَا ‏ ‏حَسَنٌ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْمُزَنِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلُّوا قَبْلَ الْمَغْرِبِ رَكْعَتَيْنِ ثُمَّ قَالَ صَلُّوا قَبْلَ الْمَغْرِبِ رَكْعَتَيْنِ ثُمَّ قَالَ عِنْدَ الثَّالِثَةِ لِمَنْ شَاءَ كَرَاهِيَةَ أَنْ يَتَّخِذَهَا النَّاسُ سُنَّةً ‏","","",""],[19644,19644,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ الْمُزَنِيُّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَغْلِبَنَّكُمْ ‏ ‏الْأَعْرَابُ ‏ ‏عَلَى اسْمِ صَلَاةِ الْمَغْرِبِ ‏ ‏قَالَ ‏ ‏وَتَقُولُ ‏ ‏الْأَعْرَابُ ‏ ‏هِيَ الْعِشَاءُ ‏","","",""],[19645,19645,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَعَامَةَ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏سَمِعَ ابْنَهُ يَقُولُ اللَّهُمَّ إِنِّي أَسْأَلُكَ الْقَصْرَ الْأَبْيَضَ عَنْ يَمِينِ الْجَنَّةِ إِذَا دَخَلْتُهَا فَقَالَ يَا بُنَيَّ سَلْ اللَّهَ تَبَارَكَ وَتَعَالَى الْجَنَّةَ وَعُذْ بِهِ مِنْ النَّارِ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَكُونُ قَوْمٌ يَعْتَدُونَ فِي الدُّعَاءِ وَالطَّهُورِ ‏","","",""],[19646,19646,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏كُنَّا مُحَاصِرِينَ قَصْرَ ‏ ‏خَيْبَرَ ‏ ‏فَأَلْقَى إِلَيْنَا ‏ ‏رَجُلٌ ‏ ‏جِرَابًا ‏ ‏فِيهِ شَحْمٌ فَذَهَبْتُ آخُذُهُ فَرَأَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَحْيَيْتُ ‏","","",""],[19647,19647,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏قَالَ سُئِلَ ‏ ‏سَعِيدٌ ‏ ‏عَنْ الصَّلَاةِ فِي أَعْطَانِ الْإِبِلِ ‏ ‏فَأَخْبَرَنَا عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ أَبِي الْحَسَنِ الْبَصْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا ‏ ‏يَعْنِي أَدْرَكْتَ الصَّلَاةَ وَأَنْتَ فِي ‏ ‏أَعْطَانِ ‏ ‏الْإِبِلِ فَلَا تُصَلِّ وَإِذَا أَدْرَكَتْكَ فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ فَصَلِّ إِنْ شِئْتَ ‏","","",""],[19648,19648,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ طَلْحَةَ بْنِ عُبَيْدِ اللَّهِ بْنِ كُرَيْزٍ الْخُزَاعِيُّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ أَبِي الْحَسَنِ الْبَصْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا تُصَلُّوا فِي ‏ ‏عَطَنِ ‏ ‏الْإِبِلِ فَإِنَّهَا مِنْ الْجِنِّ خُلِقَتْ أَلَا تَرَوْنَ عُيُونَهَا وَهِبَابَهَا إِذَا نَفَرَتْ وَصَلُّوا فِي ‏ ‏مُرَاحِ ‏ ‏الْغَنَمِ فَإِنَّهَا هِيَ أَقْرَبُ مِنْ الرَّحْمَةِ ‏","","",""],[19649,19649,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِيَاسٍ ‏ ‏أَخْبَرَنَا ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَهُوَ عَلَى نَاقَتِهِ ‏ ‏قَرَأَ سُورَةَ ‏ ‏الْفَتْحِ ‏ ‏قَالَ ‏ ‏فَقَرَأَ ‏ ‏أَبُو إِيَاسٍ ‏ ‏ثُمَّ رَجَّعَ وَقَالَ لَوْلَا أَنْ يَجْتَمِعَ النَّاسُ عَلَيَّ لَقَرَأْتُ بِهَذَا اللَّحْنِ ‏","","",""],[19650,19650,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنْ ‏ ‏أَبِي مَسْعُودٍ الْجُرَيْرِيِّ سَعِيدِ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَبَايَةَ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَأَنَا أَقْرَأُ ‏ ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏ ‏فَلَمَّا انْصَرَفَ قَالَ يَا بُنَيَّ إِيَّاكَ ‏ ‏وَالْحَدَثَ ‏ ‏فِي الْإِسْلَامِ فَإِنِّي ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِى بَكْرٍ ‏ ‏وَخَلْفَ ‏ ‏عُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏فَكَانُوا لَا يَسْتَفْتِحُونَ الْقِرَاءَةَ ‏ ‏بِبِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ وَلَمْ أَرَ رَجُلًا قَطُّ أَبْغَضَ إِلَيْهِ ‏ ‏الْحَدَثُ ‏ ‏مِنْهُ ‏","","",""],[19651,19651,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ بُرَيْدَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ مُغَفَّلٍ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ بَيْنَ كُلِّ أَذَانَيْنِ صَلَاةٌ لِمَنْ شَاءَ ‏","","",""],[19652,19652,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏حَدَّثَنِي ‏ ‏ابْنُ بُرَيْدَةَ ‏ ‏عَنِ ‏ ‏ابْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏رَأَى رَجُلًا مِنْ أَصْحَابِهِ ‏ ‏يَخْذِفُ ‏ ‏فَقَالَ لَا ‏ ‏تَخْذِفْ ‏ ‏فَإِنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَكْرَهُ ‏ ‏الْخَذْفَ ‏ ‏أَوْ قَالَ يَنْهَى عَنْهُ ‏ ‏كَهْمَسٌ ‏ ‏يَقُولُ ذَاكَ ‏ ‏فَإِنَّهَا لَا ‏ ‏يُنْكَأُ ‏ ‏بِهَا عَدُوٌّ وَلَا يُصَادُ بِهَا صَيْدٌ وَلَكِنَّهَا تَفْقَأُ الْعَيْنَ وَتَكْسِرُ ‏ ‏السِّنَّ ‏ ‏ثُمَّ رَآهُ بَعْدَ ذَلِكَ ‏ ‏يَخْذِفُ ‏ ‏فَقَالَ أُخْبِرُكَ أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَنْهَى عَنْ ‏ ‏الْخَذْفِ ‏ ‏أَوْ يَكْرَهُهُ ‏ ‏ثُمَّ أَرَاكَ ‏ ‏تَخْذِفُ ‏ ‏لَا أُكَلِّمُكَ كَلِمَةً كَذَا وَكَذَا ‏","","",""],[19653,19653,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا وَلَكِنْ اقْتُلُوا مِنْهَا كُلَّ أَسْوَدَ ‏ ‏بَهِيمٍ ‏","","",""],[19654,19654,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابُ بْنُ زِيَادٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏حَدَّثَنِي ‏ ‏أَشْعَثُ بْنُ عَبْدِ اللَّهِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَبُولَ الرَّجُلُ فِي مُسْتَحَمِّهِ فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏","","",""],[19655,19655,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ عَطِيَّةَ ‏ ‏قَالَ سَأَلَتُ ‏ ‏الْحَسَنَ ‏ ‏عَنِ ‏ ‏الرَّجُلِ يَتَّخِذُ الْكَلْبَ فِي دَارِهِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا نَقَصَ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[19656,19656,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ قُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏عَلَى نَاقَتِهِ ‏ ‏يَقْرَأُ سُورَةَ ‏ ‏الْفَتْحِ ‏ ‏قَالَ ‏ ‏فَقَرَأَ ‏ ‏ابْنُ مُغَفَّلٍ ‏ ‏وَرَجَّعَ ‏ ‏فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏لَوْلَا النَّاسُ لَأَخَذْتُ لَكُمْ بِذَاكَ الَّذِي ذَكَرَهُ ‏ ‏ابْنُ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ أَوْ حَمَلَهُ عَلَى نَاقَتِهِ قَالَ فَقَرَأَ سُورَةَ ‏ ‏الْفَتْحِ ‏ ‏فَرَجَّعَ فِيهَا ‏ ‏قَالَ ‏ ‏أَبُو إِيَاسٍ ‏ ‏لَوْلَا أَنِّي أَخْشَى أَنْ يَجْتَمِعَ النَّاسُ عَلَيَّ لَرَجَّعْتُ كَمَا رَجَّعَ ‏","","",""],[19657,19657,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا ثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفًا ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏أَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقَتْلِ الْكِلَابِ ثُمَّ قَالَ مَا لَكُمْ وَلِلْكِلَابِ ثُمَّ رَخَّصَ فِي كَلْبِ الصَّيْدِ وَالْغَنَمِ وَقَالَ فِي الْإِنَاءِ إِذَا ‏ ‏وَلَغَ ‏ ‏فِيهِ الْكَلْبُ اغْسِلُوهُ سَبْعَ مَرَّاتٍ ‏ ‏وَعَفِّرُوهُ ‏ ‏فِي الثَّامِنَةِ بِالتُّرَابِ ‏","","",""],[19658,19658,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏دُلِّيَ ‏ ‏جِرَابٌ ‏ ‏مِنْ شَحْمٍ يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏فَنَزَوْتُ ‏ ‏وَأَخَذْتُهُ فَنَظَرْتُ فَإِذَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتَحْيَيْتُ مِنْهُ ‏","","",""],[19659,19659,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا لَيْسَ بِكَلْبِ صَيْدٍ أَوْ كَلْبِ غَنَمٍ أَوْ كَلْبِ زَرْعٍ فَإِنَّهُ يُنْتَقَصُ مِنْ عَمَلِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[19660,19660,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنِي ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَبُولَنَّ أَحَدُكُمْ فِي مُسْتَحَمِّهِ ثُمَّ يَتَوَضَّأُ فِيهِ فَإِنَّ عَامَّةَ الْوَسْوَاسِ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَنْبَأَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏فَخَذَفَ ‏ ‏رَجُلٌ عِنْدَهُ مِنْ قَوْمِهِ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏إِسْمَاعِيلَ بْنِ عُلَيَّةَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏أَنَّ قَرِيبًا ‏ ‏لِعَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏خَذَفَ ‏ ‏فَنَهَاهُ ‏","","",""],[19661,19661,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ الْكِلَابَ أُمَّةٌ مِنْ الْأُمَمِ لَأَمَرْتُ بِقَتْلِهَا فَاقْتُلُوا الْأَسْوَدَ ‏ ‏الْبَهِيمَ ‏ ‏وَأَيُّمَا قَوْمٍ اتَّخَذُوا كَلْبًا لَيْسَ بِكَلْبِ صَيْدٍ أَوْ زَرْعٍ أَوْ مَاشِيَةٍ نَقَصَ مِنْ أُجُورِهِمْ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[19662,19662,"","","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي ‏ ‏مَرَابِضِ ‏ ‏الْغَنَمِ وَلَا تُصَلُّوا فِي مَبَارِكِ الْإِبِلِ فَإِنَّهَا خُلِقَتْ مِنْ الشَّيَاطِينِ ‏","","",""],[19663,19663,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَقْطَعُ الصَّلَاةَ الْمَرْأَةُ وَالْحِمَارُ وَالْكَلْبُ ‏","","",""],[19664,19664,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏عُقْبَةَ بْنِ صُهْبَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ ‏ ‏الْخَذْفِ ‏ ‏وَقَالَ إِنَّهُ لَا يُصَادُ بِهِ صَيْدٌ وَلَا ‏ ‏يُنْكَأُ ‏ ‏بِهِ عَدُوٌّ وَلَكِنَّهَا تَفْقَأُ الْعَيْنَ وَتَكْسِرُ السِّنَّ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً لَا يُصَادُ بِهَا صَيْدٌ وَلَا ‏ ‏يُنْكَأُ ‏ ‏بِهَا عَدُوٌّ ‏","","",""],[19665,19665,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏وَكَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ عِنْدَ كُلِّ أَذَانَيْنِ صَلَاةٌ لِمَنْ شَاءَ ‏","","",""],[19666,19666,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى عَلَى جَنَازَةٍ فَلَهُ ‏ ‏قِيرَاطٌ ‏ ‏فَإِنْ انْتَظَرَ حَتَّى يُفْرَغَ مِنْهَا فَلَهُ ‏ ‏قِيرَاطَانِ ‏","","",""],[19667,19667,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ اتَّخَذَ كَلْبًا لَيْسَ بِكَلْبِ صَيْدٍ وَلَا زَرْعٍ وَلَا غَنَمٍ فَإِنَّهُ يَنْقُصُ مِنْ أَجْرِهِ كُلَّ يَوْمٍ ‏ ‏قِيرَاطٌ ‏","","",""],[19668,19668,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ أَبُو زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏حَدَّثَنِي ‏ ‏فُضَيْلُ بْنُ زَيْدٍ الرَّقَاشِيُّ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏عَنْ ‏ ‏فُضَيْلِ بْنِ زَيْدٍ ‏ ‏وَقَدْ غَزَا مَعَ ‏ ‏عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏سَبْعَ غَزَوَاتٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ مُغَفَّلٍ الْمُزَنِيَّ ‏ ‏مَا حُرِّمَ عَلَيْنَا مِنْ الشَّرَابِ قَالَ الْخَمْرَةُ قَالَ فَقُلْتُ هَذَا فِي الْقُرْآنِ فَقَالَ لَا أُخْبِرُكَ إِلَّا مَا سَمِعْتُ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ رَسُولَ اللَّهِ ‏ ‏مُحَمَّدًا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِمَّا أَنْ يَكُونَ بَدَأَ بِالرِّسَالَةِ أَوْ يَكُونَ بَدَأَ ‏ ‏بِالِاسْمِ ‏ ‏فَقُلْتُ شَرْعِي بِأَنِّي اكْتَفَيْتُ قَالَ فَقَالَ ‏ ‏نَهَى عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَهُوَ ‏ ‏الْجَرُّ ‏ ‏وَنَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَهُوَ الْقَرْعُ وَنَهَى عَنْ ‏ ‏الْمُزَفَّتِ ‏ ‏وَهُوَ مَا ‏ ‏لُطِّخَ ‏ ‏بِالْقَارِ ‏ ‏مِنْ ‏ ‏زِقٍّ ‏ ‏أَوْ غَيْرِهِ وَنَهَى عَنْ ‏ ‏النَّقِيرِ ‏ ‏قَالَ ‏ ‏فَلَمَّا سَمِعْتُ ذَاكَ اشْتَرَيْتُ ‏ ‏أَفِيقَةً ‏ ‏فَهِيَ هُوَ ذَا مُعَلَّقَةٌ ‏ ‏يُنْبَذُ ‏ ‏فِيهَا ‏","","",""],[19669,19669,"","","‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ بْنُ أَبِي رَائِطَةَ الْحَذَّاءُ التَّمِيمِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ زِيَادٍ ‏ ‏أَوْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ الْمُزَنِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهَ اللَّهَ فِي أَصْحَابِي اللَّهَ اللَّهَ فِي أَصْحَابِي لَا تَتَّخِذُوهُمْ ‏ ‏غَرَضًا ‏ ‏بَعْدِي فَمَنْ أَحَبَّهُمْ فَبِحُبِّي أَحَبَّهُمْ وَمَنْ أَبْغَضَهُمْ فَبِبُغْضِي أَبْغَضَهُمْ وَمَنْ آذَاهُمْ فَقَدْ آذَانِي وَمَنْ آذَانِي فَقَدْ آذَى اللَّهَ عَزَّ وَجَلَّ وَمَنْ آذَى اللَّهَ فَيُوشِكُ أَنْ يَأْخُذَهُ ‏","","",""],[19670,19670,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَيْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏عُمُومَتِهِ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏جَاءَ رَكْبٌ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَشَهِدُوا أَنَّهُمْ رَأَوْهُ بِالْأَمْسِ يَعْنُونَ الْهِلَالَ فَأَمَرَهُمْ ‏ ‏أَنْ يُفْطِرُوا وَأَنْ يَخْرُجُوا مِنْ الْغَدِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏أُرَاهُ مِنْ آخِرِ النَّهَارِ ‏","","",""],[19671,19671,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَيْرِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏عُمُومَةٍ لَهُ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَشْهَدُهُمَا مُنَافِقٌ ‏ ‏يَعْنِي صَلَاةَ الصُّبْحِ وَالْعِشَاءِ ‏ ‏قَالَ ‏ ‏أَبُو بِشْرٍ ‏ ‏يَعْنِي ‏ ‏لَا يُوَاظِبُ عَلَيْهِمَا ‏","","",""],[19672,19672,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا أَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سَلَّامِ بْنِ عَمْرٍو ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِخْوَانُكُمْ فَأَحْسِنُوا إِلَيْهِمْ ‏ ‏أَوْ فَأَصْلِحُوا إِلَيْهِمْ ‏ ‏وَاسْتَعِينُوهُمْ عَلَى مَا غَلَبَكُمْ وَأَعِينُوهُمْ عَلَى مَا غَلَبَهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَلَّامَ بْنَ عَمْرٍو ‏ ‏وَرَجُلًا ‏ ‏مِنْ قَوْمِهِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَأَصْلِحُوا ‏","","",""],[19673,19673,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنَ الْأَنْصَارِ ‏ ‏أَنَّ رَجُلًا ‏ ‏أَوْطَأَ ‏ ‏بَعِيرَهُ ‏ ‏أُدْحِيَّ ‏ ‏نَعَامٍ وَهُوَ مُحْرِمٌ فَكَسَرَ بَيْضَهَا فَانْطَلَقَ إِلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَسَأَلَهُ عَنْ ذَلِكَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏عَلَيْكَ بِكُلِّ بَيْضَةٍ جَنِينُ نَاقَةٍ أَوْ ‏ ‏ضِرَابُ ‏ ‏نَاقَةٍ فَانْطَلَقَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ ذَلِكَ لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَدْ قَالَ ‏ ‏عَلِيٌّ ‏ ‏بِمَا سَمِعْتَ وَلَكِنْ هَلُمَّ إِلَى الرُّخْصَةِ ‏ ‏عَلَيْكَ بِكُلِّ بَيْضَةٍ صَوْمٌ أَوْ إِطْعَامُ مِسْكِينٍ ‏","","",""],[19674,19674,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏حَسْنَاءَ ‏ ‏امْرَأَةٍ مِنْ ‏ ‏بَنِي صُرَيْمٍ ‏ ‏عَنْ ‏ ‏عَمِّهَا ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏النَّبِيُّ فِي الْجَنَّةِ وَالشَّهِيدُ فِي الْجَنَّةِ وَالْمَوْلُودُ فِي الْجَنَّةِ ‏ ‏وَالْوَئِيدُ ‏ ‏فِي الْجَنَّةِ ‏","","",""],[19675,19675,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو بِشْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عُمَيْرِ بْنِ أَنَسٍ ‏ ‏حَدَّثَنِي ‏ ‏عُمُومَةٌ لِي مِنَ الْأَنْصَارِ ‏ ‏مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏غُمَّ ‏ ‏عَلَيْنَا هِلَالُ شَوَّالٍ فَأَصْبَحْنَا صِيَامًا فَجَاءَ رَكْبٌ مِنْ آخِرِ النَّهَارِ فَشَهِدُوا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُمْ رَأَوْا الْهِلَالَ بِالْأَمْسِ فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُفْطِرُوا مِنْ يَوْمِهِمْ وَأَنْ يَخْرُجُوا لِعِيدِهِمْ مِنْ الْغَدِ ‏","","",""],[19676,19676,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي الْأَزْرَقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَتْنِي ‏ ‏حَسْنَاءُ ابْنَةُ مُعَاوِيَةَ الصُّرَيْمِيَّةُ ‏ ‏عَنْ ‏ ‏عَمِّهَا ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَنْ فِي الْجَنَّةِ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏النَّبِيُّ فِي الْجَنَّةِ وَالشَّهِيدُ فِي الْجَنَّةِ وَالْمَوْلُودُ فِي الْجَنَّةِ وَالْمَوْءُودَةُ فِي الْجَنَّةِ ‏","","",""],[19677,19677,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِسْحَاقَ بْنَ سُوَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مُطَرِّفَ بْنَ عَبْدِ اللَّهِ بْنِ الشِّخِّيرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏بِالْكُوفَةِ ‏ ‏أَمِيرٌ قَالَ فَخَطَبَ يَوْمًا فَقَالَ ‏ ‏إِنَّ فِي إِعْطَاءِ هَذَا الْمَالِ فِتْنَةً وَفِي إِمْسَاكِهِ فِتْنَةً وَبِذَلِكَ قَامَ بِهِ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي خُطْبَتِهِ حَتَّى فَرَغَ ثُمَّ نَزَلَ ‏","","",""],[19678,19678,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حُمَيْدَ بْنَ هِلَالٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏أَعْرَابِيٍّ ‏ ‏أَنَّهُ ‏ ‏رَأَى عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعْلَيْنِ ‏ ‏مَخْصُوفَتَيْنِ ‏","","",""],[19679,19679,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ غِيَاثٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا السَّلِيلِ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحَدِّثُ النَّاسَ حَتَّى يُكْثَرَ عَلَيْهِ فَيَصْعَدَ عَلَى ظَهْرِ بَيْتٍ فَيُحَدِّثَ النَّاسَ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ آيَةٍ فِي الْقُرْآنِ أَعْظَمُ قَالَ فَقَالَ رَجُلٌ ‏ { ‏اللَّهُ لَا إِلَهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ ‏} ‏قَالَ فَوَضَعَ يَدَهُ بَيْنَ كَتِفَيَّ قَالَ فَوَجَدْتُ بَرْدَهَا بَيْنَ ثَدْيَيَّ ‏ ‏أَوْ قَالَ فَوَضَعَ يَدَهُ بَيْنَ ثَدْيَيَّ فَوَجَدْتُ بَرْدَهَا بَيْنَ كَتِفَيَّ ‏ ‏قَالَ ‏ ‏يَهْنِكَ ‏ ‏يَا ‏ ‏أَبَا الْمُنْذِرِ ‏ ‏الْعِلْمَ الْعِلْمَ ‏","","",""],[19680,19680,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَّهُ حَجَّ ‏ ‏مَعَ ذِي قَرَابَةٍ لَهُ مُقْتَرِنًا بِهِ فَرَآهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا هَذَا قَالَ إِنَّهُ نَذْرٌ ‏ ‏فَأَمَرَ بِالْقِرَانِ أَنْ يُقْطَعَ ‏","","",""],[19681,19681,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏وَعَبْدَةُ ‏ ‏قَالَا ثَنَا ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏أَعْطُوا كُلَّ سُورَةٍ حَظَّهَا مِنْ الرُّكُوعِ وَالسُّجُودِ ‏","","",""],[19682,19682,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَمَّنْ كَانَ رَدِيفَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُنْتُ ‏ ‏رَدِيفَهُ ‏ ‏عَلَى حِمَارٍ ‏ ‏فَعَثَرَ ‏ ‏الْحِمَارُ فَقُلْتُ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَقَالَ ‏ ‏لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُلْ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَإِنَّكَ إِذَا قُلْتَ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ تَعَاظَمَ الشَّيْطَانُ فِي نَفْسِهِ وَقَالَ صَرَعْتُهُ بِقُوَّتِي فَإِذَا قُلْتَ بِسْمِ اللَّهِ تَصَاغَرَتْ إِلَيْهِ نَفْسُهُ حَتَّى يَكُونَ أَصْغَرَ مِنْ ذُبَابٍ ‏","","",""],[19683,19683,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا تَمِيمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏رَدِيفِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏عَاصِمٌ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏رَدِيفِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَثَرَ ‏ ‏بِالنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِمَارُهُ فَقُلْتُ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُلْ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَإِنَّكَ إِذَا قُلْتَ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ تَعَاظَمَ وَقَالَ بِقُوَّتِي صَرَعْتُهُ وَإِذَا قُلْتَ بِسْمِ اللَّهِ تَصَاغَرَ حَتَّى يَصِيرَ مِثْلَ الذُّبَابِ ‏","","",""],[19684,19684,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏صَعْصَعَةَ بْنِ مُعَاوِيَةَ ‏ ‏عَمِّ ‏ ‏الْفَرَزْدَقِ ‏ ‏أَنَّهُ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَرَأَ عَلَيْهِ ‏ { ‏فَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ ‏} ‏قَالَ حَسْبِي لَا ‏ ‏أُبَالِ ‏ ‏أَنْ لَا أَسْمَعَ غَيْرَهَا ‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏قَالَ ثَنَا ‏ ‏صَعْصَعَةُ بْنُ مُعَاوِيَةَ ‏ ‏عَمُّ ‏ ‏الْفَرَزْدَقِ ‏ ‏قَالَ ‏ ‏قَدِمْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعْتُهُ يَقْرَأُ هَذِهِ الْآيَةَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[19685,19685,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏قَالَ ‏ ‏قَدِمَ عَمُّ ‏ ‏الْفَرَزْدَقِ ‏ ‏صَعْصَعَةُ ‏ ‏الْمَدِينَةَ ‏ ‏لَمَّا سَمِعَ ‏ { ‏مَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ وَمَنْ يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ ‏} ‏قَالَ حَسْبِي لَا ‏ ‏أُبَالِ ‏ ‏أَنْ لَا أَسْمَعَ غَيْرَ هَذَا ‏","","",""],[19686,19686,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مَنْصُورُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏مَيْسَرَةَ الْفَجْرِ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ مَتَى كُتِبْتَ نَبِيًّا قَالَ ‏ ‏وآدَمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏بَيْنَ الرُّوحِ وَالْجَسَدِ ‏","","",""],[19687,19687,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ ‏ ‏بَعْضِ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَيْلَةَ أُسْرِيَ بِهِ ‏ ‏مَرَرْتُ عَلَى ‏ ‏مُوسَى ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فِي قَبْرِهِ ‏","","",""],[19688,19688,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏عُمَرُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنِي ‏ ‏بِسْطَامُ ‏ ‏عَنْ ‏ ‏أَعْرَابِيٍّ ‏ ‏تَضَيَّفَهُمْ ‏ ‏أَنَّهُ ‏ ‏صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ تَسْلِيمَتَيْنِ ‏","","",""],[19689,19689,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ فَرُّوخَ ‏ ‏حَدَّثَنَا ‏ ‏بِسْطَامُ الْكُوفِيُّ ‏ ‏قَالَ ‏ ‏تَضَيَّفَنَا أَعْرَابِيٌّ فَحَدَّثَ ‏ ‏الْأَعْرَابِيُّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ صَلَّى مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمَ تَسْلِيمَتَيْنِ عَنْ يَمِينِهِ وَعَنْ شِمَالِهِ ‏","","",""],[19690,19690,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي عَائِشَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّكُمْ تَقْرَءُونَ خَلْفَ الْإِمَامِ وَالْإِمَامُ يَقْرَأُ قَالُوا إِنَّا لَنَفْعَلُ ذَلِكَ قَالَ فَلَا تَفْعَلُوا إِلَّا أَنْ يَقْرَأَ أَحَدُكُمْ ‏ ‏بِأُمِّ الْكِتَابِ ‏ ‏أَوْ قَالَ ‏ ‏فَاتِحَةِ الْكِتَابِ ‏","","",""],[19691,19691,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏هَارُونَ بْنِ رِئَابٍ ‏ ‏عَنْ ‏ ‏كِنَانَةَ بْنِ نُعَيْمٍ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ الْمُخَارِقِ ‏ ‏قَالَ ‏ ‏حُمِّلْتُ ‏ ‏حَمَالَةً ‏ ‏فَأَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْتُهُ فِيهَا فَقَالَ ‏ ‏أَقِمْ حَتَّى تَأْتِيَنَا ‏ ‏الصَّدَقَةُ ‏ ‏فَإِمَّا أَنْ نَحْمِلَهَا وَإِمَّا أَنْ نُعِينَكَ فِيهَا وَقَالَ إِنَّ الْمَسْأَلَةَ لَا تَحِلُّ إِلَّا لِثَلَاثَةٍ لِرَجُلٍ تَحَمَّلَ ‏ ‏حَمَالَةَ ‏ ‏قَوْمٍ فَيَسْأَلُ فِيهَا حَتَّى يُؤَدِّيَهَا ثُمَّ يُمْسِكُ وَرَجُلٍ أَصَابَتْهُ جَائِحَةٌ اجْتَاحَتْ مَالَهُ فَيَسْأَلُ فِيهَا حَتَّى يُصِيبَ قَوَامًا مِنْ عَيْشٍ أَوْ سِدَادًا مِنْ عَيْشٍ ثُمَّ يُمْسِكُ وَرَجُلٍ أَصَابَتْهُ ‏ ‏فَاقَةٌ ‏ ‏فَيَسْأَلُ حَتَّى يُصِيبَ قَوَامًا مِنْ عَيْشٍ أَوْ سِدَادًا مِنْ عَيْشٍ ثُمَّ يُمْسِكُ وَمَا سِوَى ذَلِكَ مِنْ الْمَسَائِلِ ‏ ‏سُحْتًا ‏ ‏يَا ‏ ‏قَبِيصَةُ ‏ ‏يَأْكُلُهُ صَاحِبُهُ ‏ ‏سُحْتًا ‏","","",""],[19692,19692,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏أَبِي كَرِيمَةَ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ الْمُخَارِقِ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لِي يَا ‏ ‏قَبِيصَةُ ‏ ‏مَا جَاءَ بِكَ قُلْتُ كَبِرَتْ سِنِّي وَرَقَّ عَظْمِي فَأَتَيْتُكَ لِتُعَلِّمَنِي مَا يَنْفَعُنِي اللَّهُ عَزَّ وَجَلَّ بِهِ قَالَ يَا ‏ ‏قَبِيصَةُ ‏ ‏مَا مَرَرْتَ بِحَجَرٍ وَلَا شَجَرٍ وَلَا ‏ ‏مَدَرٍ ‏ ‏إِلَّا اسْتَغْفَرَ لَكَ يَا ‏ ‏قَبِيصَةُ ‏ ‏إِذَا صَلَّيْتَ الْفَجْرَ فَقُلْ ثَلَاثًا ‏ ‏سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ ‏ ‏تُعَافَى مِنْ الْعَمَى ‏ ‏وَالْجُذَامِ ‏ ‏وَالْفَالِجِ ‏ ‏يَا ‏ ‏قَبِيصَةُ ‏ ‏قُلْ اللَّهُمَّ إِنِّي أَسْأَلُكَ مِمَّا عِنْدَكَ وَأَفِضْ عَلَيَّ مِنْ فَضْلِكَ وَانْشُرْ عَلَيَّ رَحْمَتَكَ وَأَنْزِلْ عَلَيَّ مِنْ بَرَكَاتِكَ ‏","","",""],[19693,19693,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏حَيَّانَ أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏قَطَنِ بْنِ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ الْمُخَارِقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْعِيَافَةَ ‏ ‏وَالطِّيَرَةَ ‏ ‏وَالطَّرْقَ ‏ ‏مِنْ ‏ ‏الْجِبْتِ ‏","","",""],[19694,19694,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏حَيَّانَ ‏ ‏حَدَّثَنِي ‏ ‏قَطَنُ بْنُ قَبِيصَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ ‏ ‏الْعِيَافَةَ ‏ ‏وَالطَّرْقَ ‏ ‏وَالطِّيَرَةَ ‏ ‏مِنْ ‏ ‏الْجِبْتِ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏الْعِيَافَةُ ‏ ‏زَجْرُ ‏ ‏الطَّيْرِ ‏ ‏وَالطَّرْقُ ‏ ‏الْخَطُّ يُخَطُّ فِي الْأَرْضِ ‏ ‏وَالْجِبْتُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏إِنَّهُ الشَّيْطَانُ ‏","","",""],[19695,19695,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏وَزُهَيْرِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏صَعِدَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَقْمَةً ‏ ‏مِنْ جَبَلٍ عَلَى أَعْلَاهَا حَجَرٌ فَجَعَلَ يُنَادِي يَا ‏ ‏بَنِي عَبْدِ مَنَافٍ ‏ ‏إِنَّمَا أَنَا نَذِيرٌ إِنَّمَا مَثَلِي وَمَثَلُكُمْ كَرَجُلٍ رَأَى الْعَدُوَّ فَذَهَبَ ‏ ‏يَرْبَأُ ‏ ‏أَهْلَهُ فَخَشِيَ أَنْ يَسْبِقُوهُ فَجَعَلَ يُنَادِي وَيَهْتِفُ يَا ‏ ‏صَبَاحَاهْ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏التَّيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ مُخَارِقٍ ‏ ‏وَزُهَيْرِ بْنِ عَمْرٍو ‏ ‏قَالَا ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏فَذَكَرَ نَحْوَهُ ‏","","",""],[19696,19696,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ ‏ ‏قَالَ ‏ ‏انْكَسَفَتْ الشَّمْسُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى رَكْعَتَيْنِ فَأَطَالَ فِيهِمَا الْقِرَاءَةَ فَانْجَلَتْ فَقَالَ ‏ ‏إِنَّ الشَّمْسَ وَالْقَمَرَ آيَتَانِ مِنْ آيَاتِ اللَّهِ تَبَارَكَ ‏ ‏وَتَعَالَى يُخَوِّفُ بِهِمَا عِبَادَهُ فَإِذَا رَأَيْتُمْ ذَلِكَ فَصَلُّوا كَأَحْدَثِ صَلَاةٍ صَلَّيْتُمُوهَا مِنْ الْمَكْتُوبَةِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ الْهِلَالِيِّ ‏ ‏قَالَ ‏ ‏انْكَسَفَتْ الشَّمْسُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا يَوْمَئِذٍ مَعَهُ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[19697,19697,"","","‏ ‏حَدَّثَنِي ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏قُرَّةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ الْعَدَوِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْهُمْ يُقَالُ لَهُ ‏ ‏خَالِدُ بْنُ عُمَيْرٍ ‏ ‏فَقَالَ ‏ ‏أَبُو نَعَامَةَ ‏ ‏سَمِعْتُهُ مِنْ ‏ ‏خَالِدِ بْنِ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏خَطَبَنَا ‏ ‏عُتْبَةُ بْنُ غَزْوَانَ ‏ ‏قَالَ ‏ ‏أَبُو نَعَامَةَ ‏ ‏عَلَى الْمِنْبَرِ ‏ ‏وَلَمْ يَقُلْهُ ‏ ‏قُرَّةُ ‏ ‏فَقَالَ أَلَا إِنَّ الدُّنْيَا قَدْ آذَنَتْ ‏ ‏بِصَرْمٍ ‏ ‏وَوَلَّتْ ‏ ‏حَذَّاءَ ‏ ‏وَلَمْ يَبْقَ مِنْهَا إِلَّا ‏ ‏صُبَابَةٌ ‏ ‏كَصُبَابَةِ ‏ ‏الْإِنَاءِ وَأَنْتُمْ فِي دَارٍ مُنْتَقِلُونَ عَنْهَا فَانْتَقِلُوا بِخَيْرِ مَا بِحَضْرَتِكُمْ فَلَقَدْ ‏ ‏رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا لَنَا طَعَامٌ نَأْكُلُهُ إِلَّا وَرَقُ الشَّجَرِ حَتَّى قَرِحَتْ ‏ ‏أَشْدَاقُنَا ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ مَا حَدَّثَ بِهَذَا الْحَدِيثِ غَيْرُ ‏ ‏وَكِيعٍ ‏ ‏يَعْنِي أَنَّهُ غَرِيبٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏أَيُّوبُ ‏ ‏أُرَاهُ ‏ ‏خَالِدَ بْنَ عُمَيْرٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عُتْبَةَ بْنَ غَزْوَانَ ‏ ‏يَخْطُبُ فَذَكَرَ الْحَدِيثَ قَالَ وَلَقَدْ رَأَيْتُنِي سَابِعَ سَبْعَةٍ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ قَالَ مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا لَنَا طَعَامٌ إِلَّا الشَّجَرَ ‏ ‏أَوْ قَالَ وَرَقَ الشَّجَرِ ‏ ‏حَتَّى قَرِحَتْ أَشْدَاقُنَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏أَبُو نَعَامَةَ ‏ ‏هَذَا ‏ ‏عَمْرُو بْنُ عِيسَى ‏ ‏وَأَبُو نَعَامَةَ السَّعْدِيُّ ‏ ‏آخَرُ أَقْدَمُ مِنْ هَذَا وَهَذَا أَكْبَرُ مِنْ ذَاكَ ‏","","",""],[19698,19698,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَغَرِّ ‏ ‏عَنْ ‏ ‏خَلِيفَةَ بْنِ حُصَيْنٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَيْسِ بْنِ عَاصِمٍ ‏ ‏أَنَّهُ أَسْلَمَ فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَغْتَسِلَ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏","","",""],[19699,19699,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏سَمِعْتُ ‏ ‏مُطَرِّفَ بْنَ الشِّخِّيرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏حَكِيمِ بْنِ قَيْسِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ أَوْصَى وَلَدَهُ عِنْدَ مَوْتِهِ قَالَ اتَّقُوا اللَّهَ عَزَّ وَجَلَّ ‏ ‏وَسَوِّدُوا ‏ ‏أَكْبَرَكُمْ فَإِنَّ الْقَوْمَ إِذَا ‏ ‏سَوَّدُوا ‏ ‏أَكْبَرَهُمْ خَلَفُوا أَبَاهُمْ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏وَإِذَا مُتُّ فَلَا تَنُوحُوا عَلَيَّ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُنَحْ عَلَيْهِ ‏","","",""],[19700,19700,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ ‏ ‏مُغِيرَةُ ‏ ‏أَخْبَرَ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ بْنِ التَّوْأَمِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَاصِمٍ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْحِلْفِ ‏ ‏فَقَالَ ‏ ‏مَا كَانَ مِنْ ‏ ‏حِلْفٍ ‏ ‏فِي الْجَاهِلِيَّةِ فَتَمَسَّكُوا بِهِ وَلَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ زِيَادٍ سَبَلَانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ بْنِ التَّوْأَمِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ عَاصِمٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19701,19701,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏الْأَغَرِّ الْمِنْقَرِيِّ ‏ ‏عَنْ ‏ ‏خَلِيفَةَ بْنِ حُصَيْنِ بْنِ قَيْسِ بْنِ عَاصِمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏أَسْلَمَ عَلَى عَهْدِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَمَرَهُ ‏ ‏أَنْ يَغْتَسِلَ بِمَاءٍ ‏ ‏وَسِدْرٍ ‏","","",""],[19702,19702,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏وَيُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ سَمُرَةَ ‏ ‏إِذَا ‏ ‏آلَيْتَ ‏ ‏عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَأْتِ الَّذِي هُوَ خَيْرٌ وَكَفِّرْ عَنْ يَمِينِكَ ‏","","",""],[19703,19703,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏حَيَّانَ بْنِ عُمَيْرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا ‏ ‏أَتَرَامَى بِأَسْهُمِي فِي حَيَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاللَّهِ إِذْ ‏ ‏كُسِفَتِ الشَّمْسُ ‏ ‏فَنَبَذْتُهُنَّ ‏ ‏وَسَعَيْتُ أَنْظُرُ مَا حَدَثَ كُسُوفِ الشَّمْسِ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِذَا هُوَ ‏ ‏رَافِعٌ يَدَيْهِ يُسَبِّحُ اللَّهَ عَزَّ وَجَلَّ وَيَحْمَدُ وَيُهَلِّلُ وَيُكَبِّرُ وَيَدْعُو فَلَمْ يَزَلْ كَذَلِكَ حَتَّى ‏ ‏حُسِرَ ‏ ‏عَنْ الشَّمْسِ فَقَرَأَ سُورَتَيْنِ وَرَكَعَ رَكْعَتَيْنِ ‏","","",""],[19704,19704,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَأْتِ الَّذِي هُوَ خَيْرٌ وَكَفِّرْ عَنْ يَمِينِكَ ‏","","",""],[19705,19705,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏كَابُلَ ‏ ‏فَأَصَابَ النَّاسُ غَنَمًا فَانْتَهَبُوهَا فَأَمَرَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏مُنَادِيًا يُنَادِي إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا فَرُدُّوا هَذِهِ الْغَنَمَ فَرَدُّوهَا فَقَسَمَهَا بِالسَّوِيَّةِ ‏","","",""],[19706,19706,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ وَأَكْبَرُ عِلْمِي أَنِّي قَدْ سَمِعْتُهُ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏نَاصِحُ بْنُ الْعَلَاءِ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏أَنَّهُ ‏ ‏مَرَّ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏وَهُوَ عَلَى نَهَرِ ‏ ‏أُمِّ عَبْدِ اللَّهِ ‏ ‏يَسِيلُ الْمَاءُ مَعَ غِلْمَتِهِ وَمَوَالِيهِ فَقَالَ لَهُ ‏ ‏عَمَّارٌ ‏ ‏يَا ‏ ‏أَبَا سَعِيدٍ ‏ ‏الْجُمُعَةَ فَقَالَ لَهُ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِذَا كَانَ يَوْمُ مَطَرٍ وَابِلٍ فَلْيُصَلِّ أَحَدُكُمْ فِي ‏ ‏رَحْلِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏نَاصِحُ بْنُ الْعَلَاءِ أَبُو الْعَلَاءِ ‏ ‏حَدَّثَنَا ‏ ‏عَمَّارُ بْنُ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏سَمِعْتُ ‏ ‏الْقَوَارِيرِيَّ ‏ ‏يَقُولُ ‏ ‏كُنْتُ أَمُرُّ بِنَاصِحٍ فَيُحَدِّثُنِي فَإِذَا سَأَلْتُهُ الزِّيَادَةَ قَالَ لَيْسَ عِنْدِي غَيْرُ ذَا وَكَانَ ضَرِيرًا ‏","","",""],[19707,19707,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ الْقُرَشِيُّ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ أُوكِلْتَ إِلَيْهَا وَإِنْ أُعْطِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَأْتِ الَّذِي هُوَ خَيْرٌ وَكَفِّرْ عَنْ يَمِينِكَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ الْجَحْدَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏سِمَاكُ بْنُ عَطِيَّةَ ‏ ‏وَيُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19708,19708,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَحْلِفُوا بِآبَائِكُمْ وَلَا ‏ ‏بِالطَّوَاغِيتِ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏وَالطَّوَاغِي ‏","","",""],[19709,19709,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏ذَكَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ فَإِنَّكَ إِنْ تُعْطَهَا عَنْ غَيْرِ مَسْأَلَةٍ تُعَنْ عَلَيْهَا وَإِنْ تُعْطَهَا عَنْ مَسْأَلَةٍ تُكَلْ إِلَيْهَا وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَأْتِ الَّذِي هُوَ خَيْرٌ وَكَفِّرْ عَنْ يَمِينِكَ ‏","","",""],[19710,19710,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ انْتَهَبَ نُهْبَةً فَلَيْسَ مِنَّا ‏","","",""],[19711,19711,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ لَهُ يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ فَإِنَّكَ إِنْ أُعْطِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا وَإِنْ أُعْطِيتَهَا ‏ ‏عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَكَفِّرْ عَنْ يَمِينِكَ وَأْتِ الَّذِي هُوَ خَيْرٌ ‏","","",""],[19712,19712,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ فَإِنَّكَ إِنْ أُوتِيتَهَا عَنْ مَسْأَلَةٍ وُكِلْتَ إِلَيْهَا وَإِنْ أُوتِيتَهَا عَنْ غَيْرِ مَسْأَلَةٍ أُعِنْتَ عَلَيْهَا وَإِذَا حَلَفْتَ عَلَى يَمِينٍ فَرَأَيْتَ غَيْرَهَا خَيْرًا مِنْهَا فَكَفِّرْ عَنْ يَمِينِكَ وَأْتِ الَّذِي هُوَ خَيْرٌ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏اتَّفَقَ ‏ ‏عَفَّانُ ‏ ‏وَأَسْوَدُ ‏ ‏فِي حَدِيثِهِمَا فَقَالَ فَكَفِّرْ عَنْ يَمِينِكَ ثُمَّ ائْتِ الَّذِي هُوَ خَيْرٌ ‏ ‏و قَالَ ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏فِي هَذَا الْحَدِيثِ ‏ ‏فَبَدَأَ بِالْكَفَّارَةِ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ الْقُرَشِيُّ ‏ ‏وَنَحْنُ ‏ ‏بِكَابُلَ ‏ ‏قَالَ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏لَا تَسْأَلْ الْإِمَارَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[19713,19713,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ بْنُ مَعْرُوفٍ ‏ ‏وَسَمِعْتُهُ ‏ ‏أَنَا مِنْ ‏ ‏هَارُونَ بْنِ مَعْرُوفٍ ‏ ‏حَدَّثَنَا ‏ ‏ضَمْرَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ شَوْذَبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏كَثِيرٍ ‏ ‏مَوْلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏عُثْمَانُ بْنُ عَفَّانَ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِأَلْفِ دِينَارٍ فِي ثَوْبِهِ حِينَ جَهَّزَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَيْشَ الْعُسْرَةِ قَالَ فَصَبَّهَا فِي حِجْرِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَلِّبُهَا بِيَدِهِ وَيَقُولُ ‏ ‏مَا ضَرَّ ‏ ‏ابْنُ عَفَّانَ ‏ ‏مَا عَمِلَ بَعْدَ الْيَوْمِ يُرَدِّدُهَا مِرَارًا ‏","","",""],[19714,19714,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏يَعْلَى بْنُ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي لَبِيدٍ ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ سَمُرَةَ ‏ ‏كَابُلَ ‏ ‏قَالَ فَأَصَابَ النَّاسُ غَنِيمَةً فَانْتَهَبُوهَا فَأَمَرَ ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ سَمُرَةَ ‏ ‏مُنَادِيًا يُنَادِي فَنَادَى فَاجْتَمَعَ النَّاسُ فَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ انْتَهَبَ فَلَيْسَ مِنَّا رُدُّوهَا فَرَدُّوهَا فَقَسَمَهَا بَيْنَهُمْ بِالسَّوِيَّةِ ‏","","",""],[19715,19715,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عُبَيْدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ رَبِّهِ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ سُلَيْمٍ ‏ ‏أَوْ ‏ ‏سُلَيْمٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ جَالِسٌ مَعَ أَصْحَابِهِ قَالَ فَقُلْتُ أَيُّكُمْ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَإِمَّا أَنْ يَكُونَ ‏ ‏أَوْمَأَ ‏ ‏إِلَى نَفْسِهِ ‏ ‏وَإِمَّا أَنْ يَكُونَ أَشَارَ إِلَيْهِ الْقَوْمُ ‏ ‏قَالَ فَإِذَا هُوَ ‏ ‏مُحْتَبٍ ‏ ‏بِبُرْدَةٍ قَدْ وَقَعَ ‏ ‏هُدْبُهَا ‏ ‏عَلَى قَدَمَيْهِ قَالَ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَجْفُو ‏ ‏عَنْ أَشْيَاءَ فَعَلِّمْنِي قَالَ ‏ ‏اتَّقِ اللَّهَ عَزَّ وَجَلَّ وَلَا تَحْقِرَنَّ مِنْ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي وَإِيَّاكَ ‏ ‏وَالْمَخِيلَةَ ‏ ‏فَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَا يُحِبُّ ‏ ‏الْمَخِيلَةَ ‏ ‏وَإِنْ امْرُؤٌ شَتَمَكَ وَعَيَّرَكَ بِأَمْرٍ يَعْلَمُهُ فِيكَ فَلَا تُعَيِّرْهُ بِأَمْرٍ تَعْلَمُهُ فِيهِ فَيَكُونَ لَكَ أَجْرُهُ وَعَلَيْهِ إِثْمُهُ وَلَا تَشْتُمَنَّ أَحَدًا ‏","","",""],[19716,19716,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏سَلَّامُ بْنُ مِسْكِينٍ ‏ ‏عَنْ ‏ ‏عَقِيلِ بْنِ طَلْحَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو جُرَىٍّ الْهُجَيْمِيُّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّا قَوْمٌ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَعَلِّمْنَا شَيْئًا يَنْفَعُنَا اللَّهُ تَبَارَكَ وَتَعَالَى بِهِ قَالَ ‏ ‏لَا تَحْقِرَنَّ مِنْ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي وَلَوْ أَنْ تُكَلِّمَ أَخَاكَ وَوَجْهُكَ إِلَيْهِ مُنْبَسِطٌ وَإِيَّاكَ وَتَسْبِيلَ ‏ ‏الْإِزَارِ ‏ ‏فَإِنَّهُ مِنْ ‏ ‏الْخُيَلَاءِ ‏ ‏وَالْخُيَلَاءُ ‏ ‏لَا يُحِبُّهَا اللَّهُ عَزَّ وَجَلَّ وَإِنْ امْرُؤٌ سَبَّكَ بِمَا يَعْلَمُ فِيكَ فَلَا تَسُبَّهُ بِمَا تَعْلَمُ فِيهِ فَإِنَّ أَجْرَهُ لَكَ وَوَبَالَهُ عَلَى مَنْ قَالَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏عَقِيلُ بْنُ طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَبِي جُرَيٍّ الْهُجَيْمِيِّ ‏ ‏أَنَّهُ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أُنَاسٍ مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَقَالُوا إِنَّا مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏فَذَكَرَ الْحَدِيثَ إِلَّا أَنَّهُ قَالَ فَلَا تَشْتُمْهُ بِمَا تَعْلَمُ فِيهِ فَإِنَّ أَجْرَ ذَلِكَ لَكَ وَوَبَالَهُ عَلَيْهِ ‏","","",""],[19717,19717,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏عَبِيدَةُ الْهُجَيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي جُرَيٍّ جَابِرِ بْنِ سُلَيْمٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏مُحْتَبٍ ‏ ‏بِشَمْلَةٍ ‏ ‏لَهُ وَقَدْ وَقَعَ ‏ ‏هُدْبُهَا ‏ ‏عَلَى قَدَمَيْهِ فَقُلْتُ أَيُّكُمْ ‏ ‏مُحَمَّدٌ ‏ ‏أَوْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَوْمَأَ ‏ ‏بِيَدِهِ إِلَى نَفْسِهِ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنِّي مِنْ أَهْلِ ‏ ‏الْبَادِيَةِ ‏ ‏وَفِيَّ ‏ ‏جَفَاؤُهُمْ ‏ ‏فَأَوْصِنِي فَقَالَ ‏ ‏لَا تَحْقِرَنَّ مِنْ الْمَعْرُوفِ شَيْئًا وَلَوْ أَنْ ‏ ‏تَلْقَى أَخَاكَ وَوَجْهُكَ مُنْبَسِطٌ وَلَوْ أَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي وَإِنْ امْرُؤٌ شَتَمَكَ بِمَا يَعْلَمُ فِيكَ فَلَا تَشْتُمْهُ بِمَا تَعْلَمُ فِيهِ فَإِنَّهُ يَكُونُ لَكَ أَجْرُهُ وَعَلَيْهِ ‏ ‏وِزْرُهُ ‏ ‏وَإِيَّاكَ ‏ ‏وَإِسْبَالَ ‏ ‏الْإِزَارِ ‏ ‏فَإِنَّ ‏ ‏إِسْبَالَ ‏ ‏الْإِزَارِ ‏ ‏مِنْ ‏ ‏الْمَخِيلَةِ ‏ ‏وَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يُحِبُّ ‏ ‏الْمَخِيلَةَ ‏ ‏وَلَا تَسُبَّنَّ أَحَدًا فَمَا سَبَبْتُ بَعْدَهُ أَحَدًا وَلَا شَاةً وَلَا بَعِيرًا ‏","","",""],[19718,19718,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَاهُ ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ الْهُجَيْمِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَلْهُجَيْمٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏إِلَامَ تَدْعُو قَالَ ‏ ‏أَدْعُو إِلَى اللَّهِ وَحْدَهُ الَّذِي إِنْ مَسَّكَ ضُرٌّ فَدَعَوْتَهُ كَشَفَ عَنْكَ وَالَّذِي إِنْ ضَلَلْتَ بِأَرْضٍ ‏ ‏قَفْرٍ ‏ ‏دَعَوْتَهُ رَدَّ عَلَيْكَ وَالَّذِي إِنْ أَصَابَتْكَ ‏ ‏سَنَةٌ ‏ ‏فَدَعَوْتَهُ أَنْبَتَ عَلَيْكَ قَالَ قُلْتُ فَأَوْصِنِي قَالَ لَا تَسُبَّنَّ أَحَدًا وَلَا تَزْهَدَنَّ فِي الْمَعْرُوفِ وَلَوْ أَنْ ‏ ‏تَلْقَى أَخَاكَ وَأَنْتَ مُنْبَسِطٌ إِلَيْهِ وَجْهُكَ وَلَوْ أَنْ تُفْرِغَ مِنْ دَلْوِكَ فِي إِنَاءِ الْمُسْتَسْقِي ‏ ‏وَاتَّزِرْ ‏ ‏إِلَى نِصْفِ السَّاقِ فَإِنْ أَبَيْتَ فَإِلَى الْكَعْبَيْنِ وَإِيَّاكَ ‏ ‏وَإِسْبَالَ ‏ ‏الْإِزَارِ ‏ ‏فَإِنَّ ‏ ‏إِسْبَالَ ‏ ‏الْإِزَارِ ‏ ‏مِنْ ‏ ‏الْمَخِيلَةِ ‏ ‏وَإِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى لَا يُحِبُّ ‏ ‏الْمَخِيلَةَ ‏","","",""],[19719,19719,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَائِذُ بْنُ عَمْرٍو ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏وَكَانَ مِنْ صَالِحِي ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏عُبَيْدِ اللَّهِ بْنِ زِيَادٍ ‏ ‏فَقَالَ إِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏شَرُّ الرِّعَاءِ ‏ ‏الْحُطَمَةُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏فَأَظُنُّهُ قَالَ إِيَّاكَ أَنْ تَكُونَ مِنْهُمْ وَلَمْ يَشُكَّ ‏ ‏يَزِيدُ ‏ ‏فَقَالَ اجْلِسْ إِنَّمَا أَنْتَ مِنْ ‏ ‏نُخَالَةِ ‏ ‏أَصْحَابِ مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَهَلْ كَانَتْ لَهُمْ ‏ ‏أَوْ فِيهِمْ ‏ ‏نُخَالَةٌ ‏ ‏إِنَّمَا كَانَتْ ‏ ‏النُّخَالَةُ ‏ ‏بَعْدَهُمْ وَفِي غَيْرِهِمْ ‏","","",""],[19720,19720,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي شِمْرٍ الضُّبَعِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏عَائِذَ بْنَ عَمْرٍو ‏ ‏يَنْهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏وَالنَّقِيرِ ‏ ‏فَقُلْتُ لَهُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ نَعَمْ ‏","","",""],[19721,19721,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ يَعْنِي التَّيْمِيَّ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏فِي مَجْلِسِ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏كَانَ فِي الْمَاءِ ‏ ‏قِلَّةٌ ‏ ‏فَتَوَضَّأَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ‏ ‏قَدَحٍ ‏ ‏أَوْ فِي ‏ ‏جَفْنَةٍ ‏ ‏فَنَصَحَنَا بِهِ قَالَ وَالسَّعِيدُ فِي أَنْفُسِنَا مَنْ أَصَابَهُ وَلَا ‏ ‏نُرَاهُ إِلَّا قَدْ أَصَابَ الْقَوْمَ كُلَّهُمْ قَالَ ثُمَّ صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضُّحَى ‏","","",""],[19722,19722,"","","‏ ‏حَدَّثَنَا ‏ ‏مُهَنَّأُ بْنُ عَبْدِ الْحَمِيدِ أَبُو شِبْلٍ ‏ ‏وَحَسَنٌ يَعْنِي ابْنَ مُوسَى ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏أَنَّ ‏ ‏سَلْمَانَ ‏ ‏وَصُهَيْبًا ‏ ‏وبِلَالًا ‏ ‏كَانُوا قُعُودًا فِي أُنَاسٍ فَمَرَّ بِهِمْ ‏ ‏أَبُو سُفْيَانَ بْنُ حَرْبٍ ‏ ‏فَقَالُوا مَا أَخَذَتْ سُيُوفُ اللَّهِ تَبَارَكَ وَتَعَالَى مِنْ عُنُقِ عَدُوِّ اللَّهِ مَأْخَذَهَا بَعْدُ فَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏أَتَقُولُونَ هَذَا لِشَيْخِ ‏ ‏قُرَيْشٍ ‏ ‏وَسَيِّدِهَا قَالَ فَأُخْبِرَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏لَعَلَّكَ أَغْضَبْتَهُمْ فَلَئِنْ كُنْتَ أَغْضَبْتَهُمْ لَقَدْ أَغْضَبْتَ رَبَّكَ تَبَارَكَ وَتَعَالَى فَرَجَعَ إِلَيْهِمْ فَقَالَ أَيْ إِخْوَتَنَا لَعَلَّكُمْ غَضِبْتُمْ ‏ ‏فَقَالُوا لَا يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏يَغْفِرُ اللَّهُ لَكَ ‏ ‏حَدَّثَنَا ‏ ‏هُدْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏مِثْلَهُ بِإِسْنَادِهِ ‏","","",""],[19723,19723,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْولُ ‏ ‏شَيْخٌ لَهُ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَحْسَبُهُ رَفَعَهُ قَالَ ‏ ‏مَنْ عَرَضَ لَهُ شَيْءٌ مِنْ هَذَا الرِّزْقِ فَلْيُوَسِّعْ بِهِ فِي رِزْقِهِ فَإِنْ كَانَ عَنْهُ غَنِيًّا ‏ ‏فَلْيُوَجِّهْهُ إِلَى مَنْ هُوَ أَحْوَجُ إِلَيْهِ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ قُرَّةَ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏أَنَّ ‏ ‏صُهَيْبًا ‏ ‏وَسَلْمَانَ ‏ ‏وَبِلَالًا ‏ ‏كَانُوا قُعُودًا فَذَكَرَ نَحْوَهُ إِلَّا أَنَّهُ قَالَ فَأَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ بِذَلِكَ فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏بِسْطَامُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَلِيفَةَ بْنَ عَبْدِ اللَّهِ الْغُبَرِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِذَ بْنَ عَمْرٍو الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ مَعَ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ حَدِيثَ الْمَسْأَلَةِ ‏","","",""],[19724,19724,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا شِمْرٍ الضُّبَعِيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِذَ بْنَ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏قُلْتُ ‏ ‏لِيَحْيَى بْنِ سَعِيدٍ الْمُزَنِيِّ ‏ ‏قَالَ نَعَمْ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْحَنْتَمِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالنَّقِيرِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[19725,19725,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عُبَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏بِسْطَامُ بْنُ مُسْلِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَلِيفَةَ بْنَ عَبْدِ اللَّهِ الْغُبَرِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِذَ بْنَ عَمْرٍو الْمُزَنِيَّ ‏ ‏قَالَ ‏ ‏بَيْنَمَا نَحْنُ مَعَ نَبِيِّنَا ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَعْرَابِيٌّ قَدْ أَلَحَّ عَلَيْهِ فِي الْمَسْأَلَةِ يَقُولُ يَا رَسُولَ اللَّهِ أَطْعِمْنِي يَا رَسُولَ اللَّهِ أَعْطِنِي قَالَ فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ الْمَنْزِلَ وَأَخَذَ ‏ ‏بِعِضَادَتَيْ ‏ ‏الْحُجْرَةِ وَأَقْبَلَ عَلَيْنَا بِوَجْهِهِ وَقَالَ وَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ ‏ ‏لَوْ تَعْلَمُونَ مَا أَعْلَمُ فِي الْمَسْأَلَةِ مَا سَأَلَ رَجُلٌ رَجُلًا وَهُوَ يَجِدُ لَيْلَةً تُبِيتُهُ فَأَمَرَ لَهُ بِطَعَامٍ ‏","","",""],[19726,19726,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا ثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏حَدَّثَنَا ‏ ‏عَامِرٌ الْأَحْوَلُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏شَيْخٌ لَهُ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏أَحْسَبُهُ رَفَعَهُ ‏ ‏قَالَ ‏ ‏مَنْ عَرَضَ لَهُ شَيْءٌ مِنْ هَذَا الرِّزْقِ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏مِنْ غَيْرِ مَسْأَلَةٍ وَلَا ‏ ‏إِشْرَافٍ ‏ ‏فَلْيُوَسِّعْ بِهِ فِي رِزْقِهِ فَإِنْ كَانَ عَنْهُ غَنِيًّا ‏ ‏فَلْيُوَجِّهْهُ إِلَى مَنْ هُوَ أَحْوَجُ إِلَيْهِ مِنْهُ ‏","","",""],[19727,19727,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏قَالَ قَالَ ‏ ‏عَائِذُ بْنُ عَمْرٍو ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ عَرَضَ لَهُ شَيْءٌ مِنْ هَذَا الرِّزْقِ مِنْ غَيْرِ مَسْأَلَةٍ وَلَا ‏ ‏إِشْرَافٍ ‏ ‏فَلْيُوَسِّعْ بِهِ فِي رِزْقِهِ فَإِنْ كَانَ عَنْهُ غَنِيًّا ‏ ‏فَلْيُوَجِّهْهُ إِلَى مَنْ هُوَ أَحْوَجُ إِلَيْهِ مِنْهُ ‏","","",""],[19728,19728,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَامِرٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏عَائِذِ بْنِ عَمْرٍو ‏ ‏قَالَ ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏أُرَاهُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ آتَاهُ اللَّهُ تَبَارَكَ وَتَعَالَى رِزْقًا مِنْ غَيْرِ مَسْأَلَةٍ فَلْيَقْبَلْهُ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَأَلْتُ أَبِي مَا الْإِشْرَافُ قَالَ تَقُولُ فِي نَفْسِكَ سَيَبْعَثُ إِلَيَّ فُلَانٌ سَيَصِلُنِي فُلَانٌ ‏","","",""],[19729,19729,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏مُشْمَعِلُّ بْنُ إِيَاسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ سُلَيْمٍ الْمُزَنِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏رَافِعَ بْنَ عَمْرٍو الْمُزَنِيَّ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْعَجْوَةُ ‏ ‏وَالصَّخْرَةُ ‏ ‏مِنْ الْجَنَّةِ ‏","","",""],[19730,19730,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ الْأُمَوِيُّ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏قَالَ ثَنَا ‏ ‏أَبُو الْعَالِيَةِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَنْ سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لِكُلِّ سُورَةٍ حَظُّهَا مِنْ الرُّكُوعِ وَالسُّجُودِ ‏ ‏قَالَ ‏ ‏ثُمَّ لَقِيتُهُ بَعْدُ فَقُلْتُ لَهُ إِنَّ ‏ ‏ابْنَ عُمَرَ ‏ ‏كَانَ يَقْرَأُ فِي الرَّكْعَةِ بِالسُّوَرِ فَتَعْرِفُ مَنْ حَدَّثَكَ هَذَا الْحَدِيثَ قَالَ إِنِّي لَأَعْرِفُهُ وَأَعْرِفُ مُنْذُ كَمْ ‏ ‏حَدَّثَنِيهِ حَدَّثَنِي مُنْذُ خَمْسِينَ سَنَةٍ ‏","","",""],[19731,19731,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏قَالَ ‏ ‏رُبَّمَا ‏ ‏أَمَّنَا ‏ ‏ابْنُ عُمَرَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏بِالسُّورَتَيْنِ وَالثَّلَاثِ ‏","","",""],[19732,19732,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏اسْتُعْمِلَ ‏ ‏الْحَكَمُ بْنُ عَمْرٍو الْغِفَارِيُّ ‏ ‏عَلَى ‏ ‏خُرَاسَانَ ‏ ‏قَالَ فَتَمَنَّاهُ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏حَتَّى قِيلَ لَهُ يَا ‏ ‏أَبَا نُجَيْدٍ ‏ ‏أَلَا نَدْعُوهُ لَكَ قَالَ لَا فَقَامَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَلَقِيَهُ بَيْنَ النَّاسِ قَالَ تَذْكُرُ يَوْمَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاعَةَ لِمَخْلُوقٍ فِي مَعْصِيَةِ اللَّهِ قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏عِمْرَانُ ‏ ‏اللَّهُ أَكْبَرُ ‏","","",""],[19733,19733,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ يَعْنِي ابْنَ هِلَالٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الصَّامِتِ ‏ ‏قَالَ ‏ ‏أَرَادَ ‏ ‏زِيَادٌ ‏ ‏أَنْ يَبْعَثَ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏عَلَى ‏ ‏خُرَاسَانَ ‏ ‏فَأَبَى عَلَيْهِمْ فَقَالَ لَهُ أَصْحَابُهُ أَتَرَكْتَ ‏ ‏خُرَاسَانَ ‏ ‏أَنْ تَكُونَ عَلَيْهَا قَالَ فَقَالَ إِنِّي وَاللَّهِ مَا يَسُرُّنِي أَنْ أُصَلِّيَ بِحَرِّهَا وَتُصَلُّونَ بِبَرْدِهَا إِنِّي أَخَافُ إِذَا كُنْتُ فِي نُحُورِ الْعَدُوِّ أَنْ يَأْتِيَنِي كِتَابٌ مِنْ ‏ ‏زِيَادٍ ‏ ‏فَإِنْ أَنَا مَضَيْتُ هَلَكْتُ وَإِنْ رَجَعْتُ ضُرِبَتْ عُنُقِي قَالَ فَأَرَادَ ‏ ‏الْحَكَمَ بْنَ عَمْرٍو الْغِفَارِيَّ ‏ ‏عَلَيْهَا قَالَ فَانْقَادَ لِأَمْرِهِ قَالَ فَقَالَ ‏ ‏عِمْرَانُ ‏ ‏أَلَا أَحَدٌ يَدْعُو لِي ‏ ‏الْحَكَمَ ‏ ‏قَالَ فَانْطَلَقَ الرَّسُولُ قَالَ فَأَقْبَلَ ‏ ‏الْحَكَمُ ‏ ‏إِلَيْهِ قَالَ فَدَخَلَ عَلَيْهِ قَالَ فَقَالَ ‏ ‏عِمْرَانُ ‏ ‏لِلْحَكَمِ ‏ ‏أَسَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا طَاعَةَ لِأَحَدٍ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ نَعَمْ ‏ ‏فَقَالَ ‏ ‏عِمْرَانُ ‏ ‏لِلَّهِ الْحَمْدُ ‏ ‏أَوْ اللَّهُ أَكْبَرُ ‏","","",""],[19734,19734,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي حَاجِبٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏بَنِي غِفَارٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ مِنْ فَضْلِ طَهُورِ الْمَرْأَةِ ‏","","",""],[19735,19735,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏قَالَ ‏ ‏جَاءَ رَجُلٌ إِلَى ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏وَنَحْنُ عِنْدَهُ فَقَالَ اسْتُعْمِلَ ‏ ‏الْحَكَمُ بْنُ عَمْرٍو الْغِفَارِيُّ ‏ ‏عَلَى ‏ ‏خُرَاسَانَ ‏ ‏فَتَمَنَّاهُ ‏ ‏عِمْرَانُ ‏ ‏حَتَّى قَالَ لَهُ رَجُلٌ مِنْ الْقَوْمِ أَلَا نَدْعُوهُ لَكَ فَقَالَ لَهُ لَا ثُمَّ قَامَ ‏ ‏عِمْرَانُ ‏ ‏فَلَقِيَهُ بَيْنَ النَّاسِ فَقَالَ ‏ ‏عِمْرَانُ ‏ ‏إِنَّكَ قَدْ وُلِّيتَ أَمْرًا مِنْ أَمْرِ الْمُسْلِمِينَ عَظِيمًا ثُمَّ أَمَرَهُ وَنَهَاهُ وَوَعَظَهُ ثُمَّ قَالَ هَلْ تَذْكُرُ يَوْمَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاعَةَ لِمَخْلُوقٍ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ ‏ ‏الْحَكَمُ ‏ ‏نَعَمْ ‏ ‏قَالَ ‏ ‏عِمْرَانُ ‏ ‏اللَّهُ أَكْبَرُ ‏","","",""],[19736,19736,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا حَاجِبٍ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْحَكَمِ بْنِ عَمْرٍو الْغِفَارِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَتَوَضَّأَ الرَّجُلُ مِنْ فَضْلِ وَضُوءِ الْمَرْأَةِ ‏","","",""],[19737,19737,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏مُحَمَّدًا ‏ ‏عَنْ حَدِيثِ ‏ ‏عِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏نُبِّئْتُ ‏ ‏أَنَّ ‏ ‏عِمْرَانَ بْنَ حُصَيْنٍ ‏ ‏قَالَ ‏ ‏لِلْحَكَمِ الْغِفَارِيِّ ‏ ‏وَكِلَاهُمَا مِنْ ‏ ‏أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ تَعْلَمُ يَوْمَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ نَعَمْ ‏ ‏قَالَ ‏ ‏عِمْرَانُ ‏ ‏اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ ‏","","",""],[19738,19738,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏أَنَّ ‏ ‏زِيَادًا ‏ ‏اسْتَعْمَلَ ‏ ‏الْحَكَمَ الْغِفَارِيَّ ‏ ‏عَلَى جَيْشٍ فَأَتَاهُ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَلَقِيَهُ بَيْنَ النَّاسِ فَقَالَ أَتَدْرِي لِمَ جِئْتُكَ فَقَالَ لَهُ لِمَ قَالَ هَلْ تَذْكُرُ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلرَّجُلِ الَّذِي قَالَ لَهُ أَمِيرُهُ قَعْ فِي النَّارِ فَأَدْرَكَ فَاحْتَبَسَ فَأُخْبِرَ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ لَوْ وَقَعَ فِيهَا لَدَخَلَا النَّارَ جَمِيعًا ‏ ‏لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ نَعَمْ قَالَ إِنَّمَا أَرَدْتُ أَنْ أُذَكِّرَكَ هَذَا الْحَدِيثَ ‏","","",""],[19739,19739,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَبِيبِ بْنِ عَبْدِ اللَّهِ الْأَزْدِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الْحَكَمِ بْنِ عَمْرٍو الْغِفَارِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَأَخِي ‏ ‏رَافِعُ بْنُ عَمْرٍو ‏ ‏عَلَى أَمِيرِ الْمُؤْمِنِينَ ‏ ‏عُمَرَ بْنِ الْخَطَّابِ ‏ ‏وَأَنَا ‏ ‏مَخْضُوبٌ ‏ ‏بِالْحِنَّاءِ وَأَخِي ‏ ‏مَخْضُوبٌ ‏ ‏بِالصُّفْرَةِ ‏ ‏فَقَالَ لِي ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏هَذَا ‏ ‏خِضَابُ ‏ ‏الْإِسْلَامِ وَقَالَ لِأَخِي ‏ ‏رَافِعٍ ‏ ‏هَذَا ‏ ‏خِضَابُ ‏ ‏الْإِيمَانِ ‏","","",""],[19740,19740,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏غَيْرِ وَاحِدٍ مِنْهُمْ ‏ ‏أَيُّوبُ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏أَنَّ ‏ ‏زِيَادًا ‏ ‏اسْتَعْمَلَ ‏ ‏الْحَكَمَ بْنَ عَمْرٍو الْغِفَارِيَّ ‏ ‏فَقَالَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏وَدِدْتُ أَنِّي أَلْقَهُ قَبْلَ أَنْ يَخْرُجَ قَالَ فَلَقِيَهُ فَقَالَ لَهُ ‏ ‏عِمْرَانُ ‏ ‏أَمَا عَلِمْتَ ‏ ‏أَوَمَا سَمِعْتَ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا طَاعَةَ لِأَحَدٍ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى قَالَ بَلَى قَالَ فَذَاكَ الَّذِي أَرَدْتُ أَنْ أَقُولَ لَكَ ‏","","",""],[19741,19741,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلِ بْنِ أَبِي عَقْرَبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّوْمِ فَقَالَ ‏ ‏صُمْ يَوْمًا مِنْ كُلِّ شَهْرٍ فَاسْتَزَادَهُ فَقَالَ بِأَبِي وَأُمِّي إِنِّي أَجِدُنِي أَقْوَى فَزِدْنِي فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَجِدُنِي قَوِيًّا إِنِّي أَجِدُنِي قَوِيًّا فَمَا كَانَ أَنْ يَزِيدَهُ فَاسْتَزَادَهُ فَقَالَ صُمْ يَوْمَيْنِ مِنْ كُلِّ شَهْرٍ قَالَ بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ إِنِّي أَجِدُنِي قَوِيًّا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَجِدُنِي قَوِيًّا إِنِّي أَجِدُنِي قَوِيًّا فَمَا كَانَ أَنْ يَزِيدَهُ فَلَمَّا أَلْحَمَ عَلَيْهِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صُمْ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[19742,19742,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ شَيْبَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا نَوْفَلِ بْنَ أَبِي عَقْرَبٍ ‏ ‏يَقُولُ ‏ ‏سَأَلَ ‏ ‏أَبِي ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الصَّوْمِ فَقَالَ ‏ ‏صُمْ يَوْمًا مِنْ كُلِّ شَهْرٍ فَقَالَ يَا رَسُولَ اللَّهِ بِأَبِي وَأُمِّي زِدْنِي قَالَ يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زِدْنِي زِدْنِي صُمْ يَوْمَيْنِ مِنْ كُلِّ شَهْرٍ فَقَالَ يَا رَسُولَ اللَّهِ بِأَبِي وَأُمِّي زِدْنِي فَإِنِّي أَجِدُنِي قَوِيًّا قَالَ يَقُولُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَجِدُنِي قَوِيًّا إِنِّي أَجِدُنِي قَوِيًّا إِنِّي أَجِدُنِي قَوِيًّا قَالَ فَأَلْحَمَ أَيْ أَمْسَكَ حَتَّى ظَنَنْتُ أَنَّهُ لَنْ يَزِيدَنِي قَالَ ثُمَّ قَالَ صُمْ ثَلَاثَةَ أَيَّامٍ مِنْ كُلِّ شَهْرٍ ‏","","",""],[19743,19743,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ يَعْنِي ابْنَ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ يَعْنِي ابْنَ هِلَالٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏الطُّفَاوَةِ ‏ ‏طَرِيقُهُ عَلَيْنَا فَأَتَى عَلَى الْحَيِّ فَحَدَّثَهُمْ قَالَ قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فِي عِيرٍ لَنَا فَبِعْنَا بِيَاعَتَنَا ثُمَّ قُلْتُ لَأَنْطَلِقَنَّ إِلَى هَذَا الرَّجُلِ فَلَآتِيَنَّ مَنْ بَعْدِي بِخَبَرِهِ قَالَ فَانْتَهَيْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا هُوَ ‏ ‏يُرِينِي بَيْتًا قَالَ إِنَّ امْرَأَةً كَانَتْ فِيهِ فَخَرَجَتْ فِي ‏ ‏سَرِيَّةٍ ‏ ‏مِنْ الْمُسْلِمِينَ وَتَرَكَتْ ثِنْتَيْ عَشْرَةَ عَنْزًا لَهَا ‏ ‏وَصِيصِيَتَهَا ‏ ‏كَانَتْ تَنْسِجُ بِهَا قَالَ فَفَقَدَتْ عَنْزًا مِنْ غَنَمِهَا ‏ ‏وَصِيصِيَتَهَا ‏ ‏فَقَالَتْ يَا رَبِّ إِنَّكَ قَدْ ضَمِنْتَ لِمَنْ خَرَجَ فِي سَبِيلِكَ أَنْ تَحْفَظَ عَلَيْهِ وَإِنِّي قَدْ فَقَدْتُ عَنْزًا مِنْ غَنَمِي ‏ ‏وَصِيصِيَتِي ‏ ‏وَإِنِّي أَنْشُدُكَ عَنْزِي ‏ ‏وَصِيصِيَتِي ‏ ‏قَالَ فَجَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَذْكُرُ شِدَّةَ مُنَاشَدَتِهَا لِرَبِّهَا تَبَارَكَ وَتَعَالَى قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَصْبَحَتْ عَنْزُهَا وَمِثْلُهَا ‏ ‏وَصِيصِيَتُهَا ‏ ‏وَمِثْلُهَا وَهَاتِيكَ فَأْتِهَا فَاسْأَلْهَا إِنْ شِئْتَ قَالَ قُلْتُ بَلْ أُصَدِّقُكَ ‏","","",""],[19744,19744,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏ذَيَّالُ بْنُ عُبَيْدِ بْنِ حَنْظَلَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَنْظَلَةَ بَنَ حِذْيَمٍ ‏ ‏جَدِّي ‏ ‏أَنَّ جَدَّهُ ‏ ‏حَنِيفَةَ ‏ ‏قَالَ ‏ ‏لِحِذْيَمٍ ‏ ‏اجْمَعْ لِي بَنِيَّ فَإِنِّي أُرِيدُ أَنْ أُوصِيَ فَجَمَعَهُمْ فَقَالَ إِنَّ أَوَّلَ مَا أُوصِي أَنَّ ‏ ‏لِيَتِيمِي هَذَا الَّذِي فِي حِجْرِي مِائَةً مِنْ الْإِبِلِ الَّتِي كُنَّا ‏ ‏نُسَمِّيهَا فِي الْجَاهِلِيَّةِ ‏ ‏الْمُطَيَّبَةَ ‏ ‏فَقَالَ ‏ ‏حِذْيَمٌ ‏ ‏يَا أَبَتْ إِنِّي سَمِعْتُ بَنِيكَ يَقُولُونَ إِنَّمَا نُقِرُّ بِهَذَا عِنْدَ أَبِينَا فَإِذَا مَاتَ رَجَعْنَا فِيهِ قَالَ فَبَيْنِي وَبَيْنَكُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏حِذْيَمٌ ‏ ‏رَضِينَا فَارْتَفَعَ ‏ ‏حِذْيَمٌ ‏ ‏وَحَنِيفَةُ ‏ ‏وحَنْظَلَةُ ‏ ‏مَعَهُمْ غُلَامٌ وَهُوَ ‏ ‏رَدِيفٌ ‏ ‏لِحِذْيَمٍ ‏ ‏فَلَمَّا أَتَوْا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَلَّمُوا عَلَيْهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا رَفَعَكَ يَا ‏ ‏أَبَا حِذْيَمٍ ‏ ‏قَالَ هَذَا وَضَرَبَ بِيَدِهِ عَلَى فَخِذِ ‏ ‏حِذْيَمٍ ‏ ‏فَقَالَ إِنِّي خَشِيتُ أَنْ يَفْجَأَنِي الْكِبَرُ أَوْ الْمَوْتُ فَأَرَدْتُ أَنْ أُوصِيَ وَإِنِّي قُلْتُ إِنَّ أَوَّلَ مَا أُوصِي أَنَّ لِيَتِيمِي هَذَا الَّذِي فِي حِجْرِي مِائَةً مِنْ الْإِبِلِ كُنَّا ‏ ‏نُسَمِّيهَا فِي الْجَاهِلِيَّةِ ‏ ‏الْمُطَيَّبَةَ ‏ ‏فَغَضِبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى رَأَيْنَا الْغَضَبَ فِي وَجْهِهِ وَكَانَ قَاعِدًا ‏ ‏فَجَثَا ‏ ‏عَلَى رُكْبَتَيْهِ وَقَالَ لَا لَا لَا ‏ ‏الصَّدَقَةُ ‏ ‏خَمْسٌ وَإِلَّا فَعَشْرٌ وَإِلَّا فَخَمْسَ عَشْرَةَ وَإِلَّا فَعِشْرُونَ وَإِلَّا فَخَمْسٌ وَعِشْرُونَ وَإِلَّا فَثَلَاثُونَ وَإِلَّا فَخَمْسٌ وَثَلَاثُونَ فَإِنْ كَثُرَتْ فَأَرْبَعُونَ قَالَ فَوَدَعُوهُ وَمَعَ الْيَتِيمِ عَصًا وَهُوَ يَضْرِبُ جَمَلًا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَظُمَتْ هَذِهِ ‏ ‏هِرَاوَةُ ‏ ‏يَتِيمٍ قَالَ ‏ ‏حَنْظَلَةُ ‏ ‏فَدَنَا بِي إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّ لِي بَنِينَ ذَوِي لِحًى وَدُونَ ذَلِكَ وَإِنَّ ذَا أَصْغَرُهُمْ فَادْعُ اللَّهَ لَهُ فَمَسَحَ رَأْسَهُ وَقَالَ بَارَكَ اللَّهُ فِيكَ ‏ ‏أَوْ بُورِكَ فِيهِ ‏ ‏قَالَ ‏ ‏ذَيَّالٌ ‏ ‏فَلَقَدْ رَأَيْتُ ‏ ‏حَنْظَلَةَ ‏ ‏يُؤْتَى بِالْإِنْسَانِ الْوَارِمِ وَجْهُهُ أَوْ الْبَهِيمَةِ الْوَارِمَةِ الضَّرْعُ فَيَتْفُلُ عَلَى يَدَيْهِ وَيَقُولُ بِسْمِ اللَّهِ وَيَضَعُ يَدَهُ عَلَى رَأْسِهِ وَيَقُولُ عَلَى مَوْضِعِ كَفِّ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَمْسَحُهُ عَلَيْهِ وَقَالَ ‏ ‏ذَيَّالٌ ‏ ‏فَيَذْهَبُ الْوَرَمُ ‏","","",""],[19745,19745,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏رَبِيعَةُ بْنُ كُلْثُومٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا غَادِيةَ ‏ ‏يَقُولُ ‏ ‏بَايَعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبُو سَعِيدٍ ‏ ‏فَقُلْتُ لَهُ بِيَمِينِكَ قَالَ نَعَمْ قَالَا جَمِيعًا فِي الْحَدِيثِ وَخَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْعَقَبَةِ ‏ ‏فَقَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ عَلَيْكُمْ حَرَامٌ إِلَى يَوْمِ تَلْقَوْنَ رَبَّكُمْ عَزَّ وَجَلَّ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا أَلَا هَلْ بَلَّغْتُ قَالُوا نَعَمْ قَالَ اللَّهُمَّ اشْهَدْ ثُمَّ قَالَ أَلَا لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ ‏","","",""],[19746,19746,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا ثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ وَجَدْتُ ‏ ‏مِرْثَدَ بْنَ ظَبْيَانَ ‏ ‏قَالَ ‏ ‏جَاءَنَا كِتَابٌ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا وَجَدْنَا لَهُ كَاتِبًا يَقْرَؤُهُ عَلَيْنَا حَتَّى قَرَأَهُ رَجُلٌ مِنْ ‏ ‏بَنِي ضُبَيْعَةَ ‏ ‏مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى ‏ ‏بَكْرِ بْنِ وَائِلٍ ‏ ‏أَسْلِمُوا تَسْلَمُوا ‏","","",""],[19747,19747,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏قَالَ ‏ ‏مَرِضَ ‏ ‏رَجُلٌ مِنْ أَصْحَابِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَخَلَ عَلَيْهِ أَصْحَابُهُ يَعُودُونَهُ فَبَكَى فَقِيلَ لَهُ مَا ‏ ‏يُبْكِيكَ يَا ‏ ‏عَبْدَ اللَّهِ ‏ ‏أَلَمْ يَقُلْ لَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُذْ مِنْ ‏ ‏شَارِبِكَ ‏ ‏ثُمَّ ‏ ‏اقْرِرْهُ ‏ ‏حَتَّى ‏ ‏تَلْقَانِي قَالَ بَلَى وَلَكِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ تَبَارَكَ وَتَعَالَى قَبَضَ قَبْضَةً بِيَمِينِهِ فَقَالَ هَذِهِ لِهَذِهِ وَلَا ‏ ‏أُبَالِ ‏ ‏وَقَبْضَةً أُخْرَى ‏ ‏يَعْنِي بِيَدِهِ الْأُخْرَى ‏ ‏فَقَالَ هَذِهِ لِهَذِهِ وَلَا ‏ ‏أُبَالِ ‏ ‏فَلَا أَدْرِي فِي أَيِّ الْقَبْضَتَيْنِ أَنَا ‏","","",""],[19748,19748,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏عَاصِمُ بْنُ هِلَالٍ ‏ ‏حَدَّثَنَا ‏ ‏غَاضِرَةُ بْنُ عُرْوَةَ الْفُقَيْمِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو عُرْوَةَ ‏ ‏قَالَ ‏ ‏كُنَّا نَنْتَظِرُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَرَجَ رَجِلًا يَقْطُرُ رَأْسُهُ مِنْ وُضُوءٍ أَوْ غُسْلٍ فَصَلَّى فَلَمَّا قَضَى الصَّلَاةَ جَعَلَ النَّاسُ يَسْأَلُونَهُ يَا رَسُولَ اللَّهِ أَعَلَيْنَا حَرَجٌ فِي كَذَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا أَيُّهَا النَّاسُ ‏ ‏إِنَّ دِينَ اللَّهِ عَزَّ وَجَلَّ فِي يُسْرٍ ثَلَاثًا يَقُولُهَا ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً جَعَلَ النَّاسُ يَقُولُونَ يَا رَسُولَ اللَّهِ مَا نَقُولُ فِي كَذَا مَا نَقُولُ فِي كَذَا ‏","","",""],[19749,19749,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عُبَيْدٍ الدِّيلِيُّ ‏ ‏عَنْ ‏ ‏عُدَيْسَةَ ابْنَةِ أُهْبَانَ بْنِ صَيْفِيٍّ ‏ ‏أَنَّهَا كَانَتْ مَعَ ‏ ‏أَبِيهَا ‏ ‏فِي مَنْزِلِهِ فَمَرِضَ فَأَفَاقَ مِنْ مَرَضِهِ ذَلِكَ فَقَامَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏بِالْبَصْرَةِ ‏ ‏فَأَتَاهُ فِي مَنْزِلِهِ حَتَّى قَامَ عَلَى بَابِ حُجْرَتِهِ فَسَلَّمَ وَرَدَّ عَلَيْهِ الشَّيْخُ السَّلَامَ فَقَالَ لَهُ ‏ ‏عَلِيٌّ ‏ ‏كَيْفَ أَنْتَ يَا ‏ ‏أَبَا مُسْلِمٍ ‏ ‏قَالَ بِخَيْرٍ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏أَلَا تَخْرُجُ مَعِي إِلَى هَؤُلَاءِ الْقَوْمِ فَتُعِينَنِي قَالَ بَلَى إِنْ رَضِيتَ بِمَا أُعْطِيكَ قَالَ ‏ ‏عَلِيٌّ ‏ ‏وَمَا هُوَ فَقَالَ الشَّيْخُ يَا جَارِيَةُ هَاتِ سَيْفِي فَأَخْرَجَتْ إِلَيْهِ غِمْدًا فَوَضَعَتْهُ فِي حِجْرِهِ ‏ ‏فَاسْتَلَّ ‏ ‏مِنْهُ طَائِفَةً ثُمَّ رَفَعَ رَأْسَهُ إِلَى ‏ ‏عَلِيٍّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَقَالَ إِنَّ خَلِيلِي ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَابْنَ عَمِّكَ عَهِدَ إِلَيَّ ‏ ‏إِذَا كَانَتْ فِتْنَةٌ بَيْنَ الْمُسْلِمِينَ أَنْ اتَّخِذْ سَيْفًا مِنْ خَشَبٍ فَهَذَا سَيْفِي فَإِنْ شِئْتَ خَرَجْتُ بِهِ مَعَكَ فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏لَا حَاجَةَ لَنَا فِيكَ وَلَا فِي سَيْفِكَ فَرَجَعَ مِنْ بَابِ الْحُجْرَةِ وَلَمْ يَدْخُلْ ‏","","",""],[19750,19750,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَمْرٍو الْقَسْمَلِيِّ ‏ ‏عَنْ ‏ ‏ابْنَةِ أُهْبَانَ ‏ ‏أَنَّ ‏ ‏عَلِيَّ بْنَ أَبِي طَالِبٍ ‏ ‏أَتَى ‏ ‏أُهْبَانَ ‏ ‏فَقَالَ مَا يَمْنَعُكَ مِنْ اتِّبَاعِي فَقَالَ أَوْصَانِي خَلِيلِي وَابْنُ عَمِّكِ ‏ ‏يَعْنِي رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏سَتَكُونُ فِتَنٌ وَفُرْقَةٌ فَإِذَا كَانَ ذَلِكَ فَاكْسِرْ سَيْفَكَ وَاتَّخِذْ سَيْفًا مِنْ خَشَبٍ فَقَدْ وَقَعَتْ الْفِتْنَةُ وَالْفُرْقَةُ وَكَسَرْتُ سَيْفِي وَاتَّخَذْتُ سَيْفًا مِنْ خَشَبٍ وَأَمَرَ أَهْلَهُ حِينَ ثَقُلَ أَنْ يُكَفِّنُوهُ وَلَا يُلْبِسُوهُ قَمِيصًا قَالَ فَأَلْبَسْنَاهُ قَمِيصًا فَأَصْبَحْنَا وَالْقَمِيصُ عَلَى ‏ ‏الْمِشْجَبِ ‏","","",""],[19751,19751,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ شَيْءٌ فَأَعْطَاهُ نَاسًا وَتَرَكَ نَاسًا ‏ ‏وَقَالَ ‏ ‏جَرِيرٌ ‏ ‏أَعْطَى رِجَالًا وَتَرَكَ رِجَالًا ‏ ‏قَالَ فَبَلَغَهُ عَنْ الَّذِينَ تَرَكَ أَنَّهُمْ ‏ ‏عَتِبُوا وَقَالُوا قَالَ فَصَعِدَ الْمِنْبَرَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ ‏ ‏إِنِّي أُعْطِي نَاسًا وَأَدَعُ نَاسًا ‏ ‏وَأُعْطِي رِجَالًا وَأَدَعُ رِجَالًا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ ذِي وَذِي ‏ ‏وَالَّذِي أَدَعُ أَحَبُّ إِلَيَّ مِنْ الَّذِي أُعْطِي أُعْطِي أُنَاسًا لِمَا فِي قُلُوبِهِمْ مِنْ ‏ ‏الْجَزَعِ ‏ ‏وَالْهَلَعِ ‏ ‏وَأَكِلُ قَوْمًا إِلَى مَا جَعَلَ اللَّهُ فِي قُلُوبِهِمْ مِنْ الْغِنَى وَالْخَيْرِ مِنْهُمْ ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ وَكُنْتُ جَالِسًا ‏ ‏تِلْقَاءَ ‏ ‏وَجْهِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا أُحِبُّ أَنَّ لِي بِكَلِمَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُمْرَ النَّعَمِ ‏","","",""],[19752,19752,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏قَالَ ثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أُعْطِي أَقْوَامًا وَأَرُدُّ آخَرِينَ وَالَّذِينَ أَدَعُ أَحَبُّ إِلَيَّ مِنْ الَّذِينَ أُعْطِي أُعْطِي أَقْوَامًا لِمَا أَخَافُ مِنْ ‏ ‏هَلَعِهِمْ ‏ ‏قَالَ ‏ ‏وَأَكِلُ أَقْوَامًا إِلَى مَا جَعَلَ اللَّهُ عَزَّ وَجَلَّ فِي قُلُوبِهِمْ مِنْ الْغِنَى وَالْخَيْرِ مِنْهُمْ ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ قَالَ ‏ ‏عَمْرٌو ‏ ‏فَوَاللَّهِ مَا أُحِبُّ أَنَّ لِي بِكَلِمَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُمْرَ النَّعَمِ ‏","","",""],[19753,19753,"","","‏ ‏حَدَّثَنَا ‏ ‏وَهْبُ بْنُ جَرِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ ثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُقَاتِلُونَ بَيْنَ يَدَيْ السَّاعَةِ قَوْمًا يَنْتَعِلُونَ الشَّعَرَ وَلَتُقَاتِلُنَّ قَوْمًا كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ الْمُطْرَقَةُ ‏","","",""],[19754,19754,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا قَوْمًا عِرَاضَ الْوُجُوهِ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ الْمُطْرَقَةُ ‏","","",""],[19755,19755,"","","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ تَغْلِبَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا أَقْوَامًا يَنْتَعِلُونَ الشَّعْرَ ‏","","",""],[19756,19756,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ تَغْلِبَ ‏ ‏قَالَ ‏ ‏سَمَعَتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا قَوْمًا نِعَالُهُمْ الشَّعْرُ ‏ ‏أَوْ يَنْتَعِلُونَ الشَّعَرَ ‏ ‏وَإِنَّ مِنْ أَشْرَاطِ السَّاعَةِ أَنْ تُقَاتِلُوا قَوْمًا عِرَاضَ الْوُجُوهِ كَأَنَّ وُجُوهَهُمْ ‏ ‏الْمَجَانُّ الْمُطْرَقَةُ ‏","","",""],[19757,19757,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ هَوْذَةَ الْقُرَيْعِيُّ ‏ ‏أَنَّهُ قَالَ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏سَمِعَ ‏ ‏جَرْمُوزًا الْهُجَيْمِيَّ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَوْصِنِي قَالَ ‏ ‏أُوصِيكَ أَنْ ‏ ‏لَا تَكُونَ ‏ ‏لَعَّانًا ‏","","",""],[19758,19758,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ يَعْنِي ابْنَ مُبَارَكٍ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏حَيَّةُ التَّمِيمِيُّ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا شَيْءَ فِي ‏ ‏الْهَامِ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ وَأَصْدَقُ ‏ ‏الطِّيَرِ ‏ ‏الْفَأْلُ ‏","","",""],[19759,19759,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏حَرْبٌ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنِي ‏ ‏حَيَّةُ بْنُ حَابِسٍ التَّمِيمِيُّ ‏ ‏أَنَّ ‏ ‏أَبَاهُ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا شَيْءَ فِي ‏ ‏الْهَامِ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ وَأَصْدَقُ ‏ ‏الطِّيَرَةِ ‏ ‏الْفَأْلُ ‏","","",""],[19760,19760,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَحَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏وَحُسَيْنُ بْنُ مُحَمَّدٍ ‏ ‏قَالَا ثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي كَثِيرٍ ‏ ‏عَنْ ‏ ‏حَيَّةَ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا شَيْءَ فِي ‏ ‏الْهَامِ ‏ ‏وَالْعَيْنُ ‏ ‏حَقٌّ وَأَصْدَقُ ‏ ‏الطِّيَرِ ‏ ‏الْفَأْلُ ‏","","",""],[19761,19761,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَطَاءُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏بِلَالِ بْنِ يَقْطُرَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتُعْمِلَ عَلَى ‏ ‏سِجِسْتَانَ ‏ ‏فَلَقِيَهُ ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ تَذْكُرُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَيْثُ اسْتَعْمَلَ رَجُلًا عَلَى جَيْشٍ وَعِنْدَهُ نَارٌ قَدْ أُجِّجَتْ فَقَالَ لِرَجُلٍ مِنْ أَصْحَابِهِ قُمْ فَانْزُهَا فَقَامَ فَنَزَاهَا فَبَلَغَ ذَلِكَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَوْ وَقَعَ فِيهَا لَدَخَلَا النَّارَ إِنَّهُ لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ تَبَارَكَ وَتَعَالَى وَإِنَّمَا أَرَدْتُ أَنْ أُذَكِّرَكَ هَذَا ‏ ‏وَقَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا قُمْ ‏ ‏فَانْزِهَا فَأَبَى فَعَزَمَ عَلَيْهِ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا لَا طَاعَةَ فِي مَعْصِيَةِ اللَّهِ تَعَالَى ‏ ‏قَالَ نَعَمْ ‏","","",""],[19762,19762,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏أَخْبَرَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏الْحَسَنُ ‏ ‏بِحَدِيثِ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عُمَرَ ‏ ‏فِي ‏ ‏الدِّيبَاجِ ‏ ‏قَالَ فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏أَخْبَرَنِي ‏ ‏رَجُلٌ مِنَ الْحَيِّ ‏ ‏أَنَّهُ دَخَلَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ جُبَّةٌ ‏ ‏لَبِنَتُهَا ‏ ‏دِيبَاجٌ ‏ ‏قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَبِنَةٌ ‏ ‏مِنْ نَارٍ ‏","","",""],[19763,19763,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏مُجَاشِعِ بْنِ مَسْعُودٍ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ هَذَا ‏ ‏مُجَالِدُ بْنُ مَسْعُودٍ ‏ ‏يُبَايِعُكَ عَلَى الْهِجْرَةِ فَقَالَ ‏ ‏لَا هِجْرَةَ بَعْدَ فَتْحِ ‏ ‏مَكَّةَ ‏ ‏وَلَكِنْ أُبَايِعُهُ عَلَى الْإِسْلَامِ ‏","","",""],[19764,19764,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏أَيُّوبُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ سَلِمَةَ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ الْفَتْحِ جَعَلَ النَّاسُ يَمُرُّونَ عَلَيْنَا قَدْ جَاءُوا مِنْ عِنْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَقْرَأُ وَأَنَا غُلَامٌ فَجَاءَ أَبِي بِإِسْلَامِ قَوْمِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَؤُمُّكُمْ أَكْثَرُكُمْ قُرْآنًا فَنَظَرُوا فَكُنْتُ أَكْثَرَهُمْ قُرْآنًا قَالَ فَقَالَتْ امْرَأَةٌ غَطُّوا ‏ ‏اسْتَ ‏ ‏قَارِئِكُمْ قَالَ فَاشْتَرَوْا لَهُ ‏ ‏بُرْدَةً ‏ ‏قَالَ فَمَا فَرِحْتُ أَشَدَّ مِنْ فَرَحِي بِذَلِكَ ‏","","",""],[19765,19765,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ وَاصِلٍ الْحَدَّادُّ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ أَبُو الْحَارِثِ الْجَرْمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ سَلِمَةَ الْجَرْمِيَّ ‏ ‏يُحَدِّثُ أَنَّ أَبَاهُ وَنَفَرًا مِنْ قَوْمِهِ وَفَدُوا إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ ظَهَرَ أَمْرُهُ وَتَعَلَّمَ النَّاسُ فَقَضَوْا حَوَائِجَهُمْ ثُمَّ سَأَلُوهُ مَنْ ‏ ‏يُصَلِّي لَنَا ‏ ‏أَوْ ‏ ‏يُصَلِّي بِنَا ‏ ‏فَقَالَ ‏ ‏يُصَلِّي لَكُمْ ‏ ‏أَوْ بِكُمْ ‏ ‏أَكْثَرُكُمْ جَمْعًا لِلْقُرْآنِ أَوْ أَخْذًا لِلْقُرْآنِ ‏ ‏فَقَدِمُوا عَلَى قَوْمِهِمْ فَسَأَلُوا فِي الْحَيِّ فَلَمْ يَجِدُوا أَحَدًا جَمَعَ أَكْثَرَ مِمَّا جَمَعْتُ فَقَدَّمُونِي بَيْنَ أَيْدِيهِمْ فَصَلَّيْتُ بِهِمْ وَأَنَا غُلَامٌ عَلَيَّ ‏ ‏شَمْلَةٌ ‏ ‏لِي قَالَ فَمَا شَهِدْتُ مَجْمَعًا مِنْ ‏ ‏جَرْمٍ ‏ ‏إِلَّا كُنْتُ إِمَامَهُمْ إِلَى يَوْمِي هَذَا ‏","","",""],[19766,19766,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ سَلِمَةَ ‏ ‏قَالَ ‏ ‏كَانُوا يَأْتُونَا ‏ ‏الرُّكْبَانُ ‏ ‏مِنْ قِبَلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَسْتَقْرِئُهُمْ فَيُحَدِّثُونَا أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لِيَؤُمَّكُمْ أَكْثَرُكُمْ قُرْآنًا ‏","","",""],[19767,19767,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏أَخْبَرَنِي ‏ ‏شَيْخٌ ‏ ‏مَنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُكَلِّمُهُ فِي ‏ ‏سَبْيٍ ‏ ‏أُصِيبَ لَنَا فِي الْجَاهِلِيَّةِ فَإِذَا هُوَ يُحَدِّثُ الْقَوْمَ وَحَلْقَةٌ قَدْ ‏ ‏أَطَافَتْ ‏ ‏بِهِ فَإِذَا هُوَ قَاعِدٌ عَلَيْهِ ‏ ‏إِزَارُ ‏ ‏قِطْرٍ لَهُ غَلِيظٌ أَوَّلُ شَيْءٍ سَمِعْتُهُ مِنْهُ يَقُولُ وَهُوَ يَقُولُ بِيَدِهِ هَكَذَا ‏ ‏وَأَشَارَ ‏ ‏الْمُبَارَكُ ‏ ‏بِإِصْبَعِهِ السَّبَّابَةِ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ التَّقْوَى هَاهُنَا التَّقْوَى هَاهُنَا أَيْ فِي الْقَلْبِ ‏","","",""],[19768,19768,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي ‏ ‏أَزْفَلَةٍ ‏ ‏مِنْ النَّاسِ فَسَمِعْتُهُ يَقُولُ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ التَّقْوَى هَاهُنَا ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَقَالَ بِيَدِهِ إِلَى صَدْرِهِ ‏ ‏وَمَا تَوَادَّ اثْنَانِ فِي اللَّهِ عَزَّ وَجَلَّ ‏ ‏لَا يُفَرِّقُ بَيْنَهُمَا إِلَّا حَدَثٌ ‏ ‏يُحْدِثُهُ أَحَدُهُمَا ‏ ‏وَالْمُحْدِثُ ‏ ‏شَرٌّ ‏ ‏وَالْمُحْدِثُ ‏ ‏شَرٌّ ‏ ‏وَالْمُحْدِثُ ‏ ‏شَرٌّ ‏","","",""],[19769,19769,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ الْأَحْوَلِ ‏ ‏عَنْ ‏ ‏أَبِي تَمِيمَةَ ‏ ‏عَنْ ‏ ‏رِدْفِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏رِدْفِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ عَلَى حِمَارٍ فَعَثَرَ فَقَالَ الَّذِي خَلْفَهُ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَقَالَ ‏ ‏لَا تَقُلْ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ فَإِنَّكَ إِذَا قُلْتَ ‏ ‏تَعِسَ ‏ ‏الشَّيْطَانُ تَعَاظَمَ وَقَالَ بِعِزَّتِي صَرَعْتُكَ وَإِذَا قُلْتَ بِسْمِ اللَّهِ تَصَاغَرَ حَتَّى يَصِيرَ مِثْلَ ذُبَابٍ ‏","","",""],[19770,19770,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَمَّنْ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ ‏ { ‏فَيَوْمَئِذٍ لَا يُعَذِّبُ عَذَابَهُ أَحَدٌ وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ ‏} ‏يَعْنِي يَفْعَلُ بِهِ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏وَسَأَلْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ أَبِي بَكْرَةَ ‏ ‏قَالَ ‏ { ‏فَيَوْمَئِذٍ لَا يُعَذِّبُ ‏} ‏أَيْ يَفْعَلُ بِهِ ‏","","",""],[19771,19771,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ يَعْمُرَ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَوَّلُ مَا يُحَاسَبُ بِهِ الْعَبْدُ يَوْمَ الْقِيَامَةِ صَلَاتُهُ فَإِنْ أَتَمَّهَا كُتِبَتْ لَهُ تَامَّةً وَإِنْ لَمْ يَكُنْ أَتَمَّهَا قَالَ انْظُرُوا تَجِدُونَ لِعَبْدِي مِنْ تَطَوُّعٍ فَأَكْمِلُوا مَا ضَيَّعَ مِنْ فَرِيضَتِهِ ثُمَّ الزَّكَاةُ ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى حَسَبِ ذَلِكَ ‏","","",""],[19772,19772,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ ‏ ‏جَلَسَ إِلَيْنَا ‏ ‏شَيْخٌ ‏ ‏فِي مَكَانِ ‏ ‏أَيُّوبَ ‏ ‏فَسَمِعَ الْقَوْمَ يَتَحَدَّثُونَ فَقَالَ حَدَّثَنِي ‏ ‏مَوْلَايَ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ مَا اسْمُهُ قَالَ ‏ ‏قُرَّةُ بْنُ دَعْمُوصٍ النُّمَيْرِيُّ ‏ ‏قَالَ قَدِمْتُ ‏ ‏الْمَدِينَةَ ‏ ‏فَأَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَوْلَهُ النَّاسُ فَجَعَلْتُ أُرِيدُ أَنْ أَدْنُوَ مِنْهُ فَلَمْ أَسْتَطِعْ فَنَادَيْتُهُ يَا رَسُولَ اللَّهِ اسْتَغْفِرْ لِلْغُلَامِ ‏ ‏النُّمَيْرِيِّ فَقَالَ غَفَرَ اللَّهُ لَكَ قَالَ وَبَعَثَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الضَّحَّاكَ بْنَ قَيْسٍ ‏ ‏سَاعِيًا فَلَمَّا رَجَعَ رَجَعَ بِإِبِلٍ ‏ ‏جُلَّةٍ ‏ ‏فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَيْتَ ‏ ‏هِلَالَ بْنَ عَامِرٍ ‏ ‏وَنُمَيْرَ بْنَ عَامِرٍ ‏ ‏وَعَامِرَ بْنَ رَبِيعَةَ ‏ ‏فَأَخَذْتَ ‏ ‏جُلَّةَ ‏ ‏أَمْوَالِهِمْ قَالَ يَا رَسُولَ اللَّهِ إِنَّنِي سَمِعْتُكَ تَذْكُرُ الْغَزْوَ فَأَحْبَبْتُ أَنْ آتِيَكَ بِإِبِلٍ تَرْكَبُهَا وَتَحْمِلُ عَلَيْهَا فَقَالَ ‏ ‏وَاللَّهِ لَلَّذِي تَرَكْتَ أَحَبُّ إِلَيَّ مِنْ الَّذِي أَخَذْتَ ارْدُدْهَا وَخُذْ مِنْ ‏ ‏حَوَاشِي ‏ ‏أَمْوَالِهِمْ صَدَقَاتِهِمْ قَالَ فَسَمِعْتُ الْمُسْلِمِينَ يُسَمُّونَ تِلْكَ الْإِبِلَ الْمَسَانَّ الْمُجَاهِدَاتِ ‏","","",""],[19773,19773,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏رِبْعِيِّ بْنِ حِرَاشٍ ‏ ‏عَنْ ‏ ‏طُفَيْلِ بْنِ سَخْبَرَةَ ‏ ‏أَخِي ‏ ‏عَائِشَةَ ‏ ‏لِأُمِّهَا ‏ ‏أَنَّهُ رَأَى فِيمَا يَرَى النَّائِمُ كَأَنَّهُ مَرَّ ‏ ‏بِرَهْطٍ ‏ ‏مِنْ ‏ ‏الْيَهُودِ ‏ ‏فَقَالَ مَنْ أَنْتُمْ قَالُوا نَحْنُ ‏ ‏الْيَهُودُ ‏ ‏قَالَ إِنَّكُمْ أَنْتُمْ الْقَوْمُ لَوْلَا أَنَّكُمْ تَزْعُمُونَ أَنَّ ‏ ‏عُزَيْرًا ‏ ‏ابْنُ اللَّهِ فَقَالَتْ ‏ ‏الْيَهُودُ ‏ ‏وَأَنْتُمْ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ مَا شَاءَ اللَّهُ وَشَاءَ ‏ ‏مُحَمَّدٌ ‏ ‏ثُمَّ مَرَّ بِرَهْطٍ مِنْ ‏ ‏النَّصَارَى ‏ ‏فَقَالَ مَنْ أَنْتُمْ قَالُوا نَحْنُ ‏ ‏النَّصَارَى ‏ ‏فَقَالَ إِنَّكُمْ أَنْتُمْ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ ‏ ‏الْمَسِيحُ ‏ ‏ابْنُ اللَّهِ قَالُوا وَإِنَّكُمْ أَنْتُمْ الْقَوْمُ لَوْلَا أَنَّكُمْ تَقُولُونَ مَا شَاءَ اللَّهُ وَمَا شَاءَ ‏ ‏مُحَمَّدٌ ‏ ‏فَلَمَّا أَصْبَحَ أَخْبَرَ بِهَا مَنْ أَخْبَرَ ثُمَّ أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ هَلْ أَخْبَرْتَ بِهَا أَحَدًا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ نَعَمْ ‏ ‏فَلَمَّا صَلَّوْا خَطَبَهُمْ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ إِنَّ ‏ ‏طُفَيْلًا ‏ ‏رَأَى رُؤْيَا فَأَخْبَرَ بِهَا مَنْ أَخْبَرَ مِنْكُمْ وَإِنَّكُمْ كُنْتُمْ تَقُولُونَ كَلِمَةً كَانَ يَمْنُعُنِي الْحَيَاءُ مِنْكُمْ أَنْ ‏ ‏أَنْهَاكُمْ عَنْهَا قَالَ ‏ ‏لَا تَقُولُوا مَا شَاءَ اللَّهُ وَمَا شَاءَ ‏ ‏مُحَمَّدٌ ‏","","",""],[19774,19774,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي حُرَّةَ الرَّقَاشِيِّ ‏ ‏عَنْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏كُنْتُ آخِذًا ‏ ‏بِزِمَامِ ‏ ‏نَاقَةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أَوْسَطِ ‏ ‏أَيَّامِ التَّشْرِيقِ ‏ ‏أَذُودُ ‏ ‏عَنْهُ النَّاسَ فَقَالَ يَا أَيُّهَا النَّاسُ أَتَدْرُونَ فِي أَيِّ شَهْرٍ أَنْتُمْ وَفِي أَيِّ يَوْمٍ أَنْتُمْ وَفِي أَيِّ بَلَدٍ أَنْتُمْ قَالُوا فِي يَوْمٍ حَرَامٍ وَشَهْرٍ حَرَامٍ وَبَلَدٍ حَرَامٍ قَالَ ‏ ‏فَإِنَّ دِمَاءَكُمْ وَأَمْوَالَكُمْ وَأَعْرَاضَكُمْ عَلَيْكُمْ حَرَامٌ كَحُرْمَةِ يَوْمِكُمْ هَذَا فِي شَهْرِكُمْ هَذَا فِي بَلَدِكُمْ هَذَا إِلَى يَوْمِ تَلْقَوْنَهُ ثُمَّ قَالَ اسْمَعُوا مِنِّي تَعِيشُوا أَلَا لَا تَظْلِمُوا أَلَا لَا تَظْلِمُوا أَلَا لَا تَظْلِمُوا إِنَّهُ لَا يَحِلُّ مَالُ امْرِئٍ إِلَّا بِطِيبِ نَفْسٍ مِنْهُ ‏ ‏أَلَا وَإِنَّ كُلَّ دَمٍ وَمَالٍ ‏ ‏وَمَأْثَرَةٍ ‏ ‏كَانَتْ فِي الْجَاهِلِيَّةِ تَحْتَ قَدَمِي هَذِهِ إِلَى يَوْمِ الْقِيَامَةِ وَإِنَّ أَوَّلَ دَمٍ يُوضَعُ دَمُ ‏ ‏رَبِيعَةَ بْنِ الْحَارِثِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏كَانَ مُسْتَرْضِعًا فِي ‏ ‏بَنِي لَيْثٍ ‏ ‏فَقَتَلَتْهُ ‏ ‏هُذَيْلٌ ‏ ‏أَلَا وَإِنَّ كُلَّ رِبًا كَانَ فِي الْجَاهِلِيَّةِ مَوْضُوعٌ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَضَى أَنَّ أَوَّلَ رِبًا يُوضَعُ رِبَا ‏ ‏الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ ‏ ‏لَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ أَلَا وَإِنَّ الزَّمَانَ قَدْ اسْتَدَارَ كَهَيْئَتِهِ يَوْمَ خَلَقَ اللَّهُ السَّمَوَاتِ وَالْأَرْضَ ثُمَّ قَرَأَ ‏ { ‏إِنَّ عِدَّةَ الشُّهُورِ عِنْدَ اللَّهِ اثْنَا عَشَرَ شَهْرًا فِي كِتَابِ اللَّهِ يَوْمَ خَلَقَ السَّمَوَاتِ وَالْأَرْضَ مِنْهَا أَرْبَعَةٌ حُرُمٌ ذَلِكَ الدِّينُ ‏ ‏الْقَيِّمُ ‏ ‏فَلَا تَظْلِمُوا فِيهِنَّ أَنْفُسَكُمْ ‏} ‏أَلَا لَا تَرْجِعُوا بَعْدِي كُفَّارًا يَضْرِبُ بَعْضُكُمْ رِقَابَ بَعْضٍ أَلَا إِنَّ الشَّيْطَانَ قَدْ أَيِسَ أَنْ يَعْبُدَهُ الْمُصَلُّونَ وَلَكِنَّهُ فِي ‏ ‏التَّحْرِيشِ ‏ ‏بَيْنَكُمْ فَاتَّقُوا اللَّهَ عَزَّ وَجَلَّ فِي النِّسَاءِ فَإِنَّهُنَّ عِنْدَكُمْ ‏ ‏عَوَانٌ ‏ ‏لَا يَمْلِكْنَ لِأَنْفُسِهِنَّ شَيْئًا وَإِنَّ لَهُنَّ عَلَيْكُمْ وَلَكُمْ عَلَيْهِنَّ حَقًّا أَنْ لَا ‏ ‏يُوطِئْنَ ‏ ‏فُرُشَكُمْ أَحَدًا غَيْرَكُمْ وَلَا يَأْذَنَّ فِي بُيُوتِكُمْ لِأَحَدٍ تَكْرَهُونَهُ فَإِنْ خِفْتُمْ ‏ ‏نُشُوزَهُنَّ ‏ ‏فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِي ‏ ‏الْمَضَاجِعِ ‏ ‏وَاضْرِبُوهُنَّ ضَرْبًا غَيْرَ ‏ ‏مُبَرِّحٍ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏قُلْتُ ‏ ‏لِلْحَسَنِ ‏ ‏مَا الْمُبَرِّحُ قَالَ الْمُؤَثِّرُ ‏ ‏وَلَهُنَّ رِزْقُهُنَّ وَكِسْوَتُهُنَّ بِالْمَعْرُوفِ وَإِنَّمَا أَخَذْتُمُوهُنَّ بِأَمَانَةِ اللَّهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللَّهِ عَزَّ وَجَلَّ وَمَنْ كَانَتْ عِنْدَهُ أَمَانَةٌ فَلْيُؤَدِّهَا إِلَى مَنْ ائْتَمَنَهُ عَلَيْهَا وَبَسَطَ يَدَيْهِ فَقَالَ أَلَا هَلْ بَلَّغْتُ أَلَا هَلْ بَلَّغْتُ أَلَا هَلْ بَلَّغْتُ ثُمَّ قَالَ لِيُبَلِّغْ الشَّاهِدُ الْغَائِبَ فَإِنَّهُ رُبَّ مُبَلَّغٍ أَسْعَدُ مِنْ سَامِعٍ ‏ ‏قَالَ ‏ ‏حُمَيْدٌ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏حِينَ بَلَّغَ هَذِهِ الْكَلِمَةَ قَدْ وَاللَّهِ بَلَّغُوا أَقْوَامًا كَانُوا أَسْعَدَ بِهِ ‏","","",""],[19775,19775,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏دَاوُدُ بْنُ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏يُقَالُ لَهُ ‏ ‏عَمَّارٌ ‏ ‏قَالَ ‏ ‏أَدْرَبْنَا عَامًا ثُمَّ قَفَلْنَا وَفِينَا ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏خَثْعَمٍ ‏ ‏فَذُكِرَ ‏ ‏الْحَجَّاجُ ‏ ‏فَوَقَعَ فِيهِ وَشَتَمَهُ فَقُلْتُ لَهُ لِمَ تَسُبُّهُ وَهُوَ يُقَاتِلُ أَهْلَ ‏ ‏الْعِرَاقِ ‏ ‏فِي طَاعَةِ أَمِيرِ الْمُؤْمِنِينَ فَقَالَ إِنَّهُ هُوَ الَّذِي أَكْفَرَهُمْ ثُمَّ قَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏يَكُونُ فِي هَذِهِ الْأُمَّةِ خَمْسُ فِتَنٍ فَقَدْ مَضَتْ أَرْبَعٌ وَبَقِيَتْ وَاحِدَةٌ وَهِيَ ‏ ‏الصَّيْلَمُ ‏ ‏وَهِيَ فِيكُمْ يَا أَهْلَ ‏ ‏الشَّامِ ‏ ‏فَإِنْ أَدْرَكْتَهَا فَإِنْ اسْتَطَعْتَ أَنْ تَكُونَ حَجَرًا فَكُنْهُ وَلَا تَكُنْ مَعَ وَاحِدٍ مِنْ الْفَرِيقَيْنِ أَلَا فَاتَّخِذْ نَفَقًا فِي الْأَرْضِ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏وَلَا تَكُنْ ‏ ‏وَقَدْ حَدَّثَنَا بِهِ ‏ ‏حَمَّادٌ ‏ ‏قَبْلَ ذَا قُلْتُ أَأَنْتَ سَمِعْتَهُ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ نَعَمْ قُلْتُ يَرْحَمُكَ اللَّهُ أَفَلَا كُنْتَ أَعْلَمْتَنِي أَنَّكَ رَأَيْتَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أُسَائِلَكَ ‏","","",""],[19776,19776,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَمَّارٌ يَعْنِي ابْنَ أَبِي عَمَّارٍ ‏ ‏عَنِ ‏ ‏ابْنِ عَبَّاسٍ ‏ ‏قَالَ ‏ ‏أَتَى عَلَيَّ زَمَانٌ وَأَنَا أَقُولُ أَوْلَادُ الْمُسْلِمِينَ مَعَ الْمُسْلِمِينَ وَأَوْلَادُ الْمُشْرِكِينَ مَعَ الْمُشْرِكِينَ حَتَّى ‏ ‏حَدَّثَنِي ‏ ‏فُلَانٌ ‏ ‏عَنْ ‏ ‏فُلَانٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْهُمْ فَقَالَ ‏ ‏اللَّهُ أَعْلَمُ بِمَا كَانُوا عَامِلِينَ قَالَ فَلَقِيتُ الرَّجُلَ فَأَخْبَرَنِي فَأَمْسَكْتُ عَنْ قَوْلِي ‏","","",""],[19777,19777,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شَيْخًا ‏ ‏مِنْ ‏ ‏قَيْسٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ قَالَ ‏ ‏جَاءَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعِنْدَنَا ‏ ‏بَكْرَةٌ ‏ ‏صَعْبَةٌ لَا يُقْدَرُ عَلَيْهَا قَالَ ‏ ‏فَدَنَا ‏ ‏مِنْهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَسَحَ ضَرْعَهَا فَحَفَلَ فَاحْتَلَبَ قَالَ وَلَمَّا مَاتَ أَبِي جَاءَ وَقَدْ شَدَدْتُهُ فِي كَفَنِهِ وَأَخَذْتُ ‏ ‏سُلَّاءَةً ‏ ‏فَشَدَدْتُ بِهَا الْكَفَنَ فَقَالَ لَا تُعَذِّبْ أَبَاكَ ‏ ‏بِالسُّلَّى ‏ ‏قَالَهَا ‏ ‏حَمَّادٌ ‏ ‏ثَلَاثًا ‏ ‏قَالَ ثُمَّ كَشَفَ عَنْ صَدْرِهِ وَأَلْقَى ‏ ‏السُّلَّى ‏ ‏ثُمَّ بَزَقَ عَلَى صَدْرِهِ حَتَّى رَأَيْتُ ‏ ‏رُضَاضَ ‏ ‏بُزَاقِهِ عَلَى صَدْرِهِ ‏","","",""],[19778,19778,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ رِفَاعَةَ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي سَلِمَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏سُلَيْمٌ ‏ ‏أَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏مُعَاذَ بْنَ جَبَلٍ ‏ ‏يَأْتِينَا بَعْدَمَا نَنَامُ وَنَكُونُ فِي أَعْمَالِنَا بِالنَّهَارِ فَيُنَادِي بِالصَّلَاةِ فَنَخْرُجُ إِلَيْهِ فَيُطَوِّلُ عَلَيْنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏مُعَاذُ بْنَ جَبَلٍ ‏ ‏لَا تَكُنْ ‏ ‏فَتَّانًا ‏ ‏إِمَّا أَنْ تُصَلِّيَ مَعِي وَإِمَّا أَنْ تُخَفِّفَ عَلَى قَوْمِكَ ثُمَّ قَالَ يَا ‏ ‏سُلَيْمُ ‏ ‏مَاذَا مَعَكَ مِنْ الْقُرْآنِ قَالَ إِنِّي أَسْأَلُ اللَّهَ الْجَنَّةَ وَأَعُوذُ بِهِ مِنْ النَّارِ وَاللَّهِ مَا أُحْسِنُ ‏ ‏دَنْدَنَتَكَ ‏ ‏وَلَا ‏ ‏دَنْدَنَةَ ‏ ‏مُعَاذٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهَلْ تَصِيرُ ‏ ‏دَنْدَنَتِي ‏ ‏وَدَنْدَنَةُ ‏ ‏مُعَاذٍ ‏ ‏إِلَّا أَنْ نَسْأَلَ اللَّهَ الْجَنَّةَ وَنَعُوذَ بِهِ مِنْ النَّارِ ‏ ‏ثُمَّ قَالَ ‏ ‏سُلَيْمٌ ‏ ‏سَتَرَوْنَ غَدًا إِذَا الْتَقَى الْقَوْمُ إِنْ شَاءَ اللَّهُ قَالَ وَالنَّاسُ يَتَجَهَّزُونَ إِلَى ‏ ‏أُحُدٍ ‏ ‏فَخَرَجَ وَكَانَ فِي الشُّهَدَاءِ رَحْمَةُ اللَّهِ وَرِضْوَانُهُ عَلَيْهِ ‏","","",""],[19779,19779,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏كَانَ مَطِيرًا قَالَ فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنَادِيَهُ أَنَّ ‏ ‏الصَّلَاةَ فِي ‏ ‏الرِّحَالِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ سَوَاءً ‏","","",""],[19780,19780,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنَا عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ كَانُوا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَأَصَابَهُمْ مَطَرٌ فَنَادَى مُنَادِيَهُ أَنْ ‏ ‏صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏","","",""],[19781,19781,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فِي يَوْمٍ مَطِيرٍ ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19782,19782,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ الْعِشَاءَ الْآخِرَةَ ‏ ‏بِالْبَصْرَةِ ‏ ‏وَمُطِرْنَا ثُمَّ جِئْتُ أَسْتَفْتِحُ قَالَ فَقَالَ لِي ‏ ‏أَبُو أُسَامَةَ ‏ ‏رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏مُطِرْنَا فَلَمْ تَبُلَّ السَّمَاءُ أَسَافِلَ نِعَالِنَا فَنَادَى مُنَادِي النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏","","",""],[19783,19783,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحُدَيْبِيَةِ ‏ ‏فَأَصَابَنَا مَطَرٌ لَمْ يَبُلَّ أَسْفَلَ نِعَالِنَا فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏","","",""],[19784,19784,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جُلُودِ ‏ ‏السِّبَاعِ ‏","","",""],[19785,19785,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ بْنِ أُسَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجْتُ إِلَى الْمَسْجِدِ فِي لَيْلَةٍ مَطِيرَةٍ فَلَمَّا رَجَعْتُ اسْتَفْتَحْتُ فَقَالَ ‏ ‏أَبِي ‏ ‏مَنْ هَذَا قَالُوا ‏ ‏أَبُو الْمَلِيحِ ‏ ‏قَالَ لَقَدْ رَأَيْتُنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَمَنَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏وَأَصَابَتْنَا سَمَاءٌ لَمْ تَبُلَّ أَسَافِلَ نِعَالِنَا فَنَادَى مُنَادِي رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ ‏ ‏صَلُّوا فِي ‏ ‏رِحَالِكُمْ ‏","","",""],[19786,19786,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتٍ يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَقْبَلُ صَلَاةً بِغَيْرِ طُهُورٍ وَلَا ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏","","",""],[19787,19787,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ السُّهَيْمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا مِنْ قَوْمِهِ أَعْتَقَ ‏ ‏شَقِيصًا ‏ ‏لَهُ مِنْ مَمْلُوكٍ فَرَفَعَ ذَلِكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَعَلَ ‏ ‏خَلَاصَهُ ‏ ‏عَلَيْهِ فِي مَالِهِ وَقَالَ ‏ ‏لَيْسَ لِلَّهِ تَبَارَكَ وَتَعَالَى شَرِيكٌ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏هَمَّامٍ ‏ ‏قَالَ ‏ ‏حَدِيثُ ‏ ‏الشَّقِيصِ ‏ ‏فِي الْعَبْدِ مُرْسَلٌ ‏","","",""],[19788,19788,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏أَنَّ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏أَخْبَرَهُ عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏كَانَ يَوْمًا مَطِيرًا فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنَادِيَهُ يُنَادِي ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19789,19789,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ جُلُودِ ‏ ‏السِّبَاعِ ‏","","",""],[19790,19790,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُمْ أَصَابَهُمْ مَطَرٌ ‏ ‏بِحُنَيْنٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلُّوا فِي ‏ ‏الرِّحَالِ ‏","","",""],[19791,19791,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْمَلِيحِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَقْبَلُ ‏ ‏صَدَقَةً ‏ ‏مِنْ ‏ ‏غُلُولٍ ‏ ‏وَلَا صَلَاةً بِغَيْرِ طُهُورٍ ‏","","",""],[19792,19792,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ وَهُوَ ابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ شَهِدَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِحُنَيْنٍ ‏ ‏فِي يَوْمٍ مَطِيرٍ أَمَرَ مُنَادِيَهُ فَيُنَادِي إِنَّ ‏ ‏الصَّلَاةَ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19793,19793,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامُ بْنُ يَحْيَى ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏هُذَيْلٍ ‏ ‏أَعْتَقَ ‏ ‏شَقِيصًا ‏ ‏لَهُ مِنْ مَمْلُوكٍ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ حُرٌّ كُلُّهُ لَيْسَ لِلَّهِ تَبَارَكَ وَتَعَالَى شَرِيكٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ وَلَمْ يَذْكُرْ عَنْ أَبِيهِ ‏","","",""],[19794,19794,"","","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادٌ يَعْنِي ابْنَ الْعَوَّامِ ‏ ‏عَنِ ‏ ‏الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْخِتَانُ ‏ ‏سُنَّةٌ لِلرِّجَالِ مَكْرُمَةٌ لِلنِّسَاءِ ‏","","",""],[19795,19795,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ مُنَادِيَهُ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فِي يَوْمٍ مَطِيرٍ فَنَادَى ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19796,19796,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ الْخُرَاسَانِيِّ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏نُبَيْشَةُ الْهُذَلِيُّ ‏ ‏يُحَدِّثُ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ الْمُسْلِمَ إِذَا اغْتَسَلَ يَوْمَ الْجُمُعَةِ ثُمَّ أَقْبَلَ إِلَى الْمَسْجِدِ لَا يُؤْذِي أَحَدًا فَإِنْ لَمْ يَجِدْ الْإِمَامَ خَرَجَ صَلَّى مَا بَدَا لَهُ وَإِنْ وَجَدَ الْإِمَامَ قَدْ خَرَجَ جَلَسَ فَاسْتَمَعَ وَأَنْصَتَ حَتَّى يَقْضِيَ الْإِمَامُ جُمُعَتَهُ وَكَلَامَهُ إِنْ لَمْ يُغْفَرْ لَهُ فِي جُمُعَتِهِ تِلْكَ ذُنُوبُهُ كُلُّهَا أَنْ تَكُونَ كَفَّارَةً لِلْجُمُعَةِ الَّتِي قَبْلَهَا ‏","","",""],[19797,19797,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏نُبَيْشَةَ الْهُذَلِيِّ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيَّامُ التَّشْرِيقِ ‏ ‏أَيَّامُ أَكْلٍ وَشُرْبٍ وَذِكْرِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[19798,19798,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏نُبَيْشَةَ الْهُذَلِيِّ ‏ ‏قَالَ ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّا كُنَّا ‏ ‏نَعْتِرُ ‏ ‏عَتِيرَةً ‏ ‏فِي الْجَاهِلِيَّةِ فَمَا تَأْمُرُنَا قَالَ ‏ ‏اذْبَحُوا لِلَّهِ عَزَّ وَجَلَّ فِي أَيِّ شَهْرٍ مَا كَانَ وَبَرُّوا اللَّهَ تَبَارَكَ وَتَعَالَى وَأَطْعِمُوا قَالُوا يَا رَسُولَ اللَّهِ إِنَّا كُنَّا ‏ ‏نُفَرِّعُ ‏ ‏فِي الْجَاهِلِيَّةِ ‏ ‏فَرَعًا ‏ ‏فَمَا تَأْمُرُنَا قَالَ فِي كُلِّ ‏ ‏سَائِمَةٍ ‏ ‏فَرَعٌ ‏ ‏تَغْذُوهُ مَاشِيَتُكَ حَتَّى إِذَا ‏ ‏اسْتَحْمَلَ ‏ ‏ذَبَحْتَهُ فَتَصَدَّقْتَ بِلَحْمِهِ ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏أُرَاهُ قَالَ عَلَى ابْنِ السَّبِيلِ ‏ ‏فَإِنَّ ذَلِكَ هُوَ خَيْرٌ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّا كُنَّا نَهَيْنَاكُمْ أَنْ تَأْكُلُوا لُحُومَهَا فَوْقَ ثَلَاثٍ كَيْ تَسَعَكُمْ فَقَدْ جَاءَ اللَّهُ بِالسَّعَةِ فَكُلُوا وَادَّخِرُوا وَاتَّجِرُوا أَلَا وَإِنَّ هَذِهِ الْأَيَّامَ أَيَّامُ أَكْلٍ ‏ ‏وَشُرْبٍ وَذِكْرِ اللَّهِ تَبَارَكَ وَتَعَالَى ‏ ‏قَالَ ‏ ‏خَالِدٌ ‏ ‏قُلْتُ ‏ ‏لِأَبِي قِلَابَةَ ‏ ‏كَمْ ‏ ‏السَّائِمَةُ ‏ ‏قَالَ مِائَةٌ ‏","","",""],[19799,19799,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏الْمُعَلَّى بْنُ رَاشِدٍ الْهُذَلِيُّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏أُمُّ عَاصِمٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏هُذَيْلٍ ‏ ‏يُقَالُ لَهُ ‏ ‏نُبَيْشَةُ الْخَيْرِ ‏ ‏وَكَانَتْ لَهُ صُحْبَةٌ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيْنَا ‏ ‏نُبَيْشَةُ ‏ ‏وَنَحْنُ نَأْكُلُ فِي ‏ ‏قَصْعَةٍ ‏ ‏فَقَالَ لَنَا حَدَّثَنَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ مَنْ أَكَلَ فِي ‏ ‏قَصْعَةٍ ‏ ‏ثُمَّ ‏ ‏لَحَسَهَا اسْتَغْفَرَتْ لَهُ ‏ ‏الْقَصْعَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحُ بْنُ عَبْدِ المُؤْمِنِ ‏ ‏وَعُبَيْدُ اللَّهِ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏مُحَمَّدُ بْنُ صُدْرَانَ ‏ ‏قَالُوا ثَنَا ‏ ‏الْمُعَلَّى بْنُ رَاشِدٍ ‏ ‏قَالَ ‏ ‏أَحَدُ الْمُحَدِّثِينَ فِيهِ ‏ ‏أَبُو الْيَمَانِ النَبَّالُ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏جَدَّتِي ‏ ‏أُمُّ عَاصِمٍ ‏ ‏عَنْ ‏ ‏نُبَيْشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِنَحْوِهِ ‏","","",""],[19800,19800,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏حَدَّثَنَا عَنْ ‏ ‏جَمِيلٍ ‏ ‏عَنْ ‏ ‏أَبِي مَلِيحٍ ‏ ‏عَنْ ‏ ‏نُبَيْشَةَ ‏ ‏قَالَ ‏ ‏ذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُنَّا ‏ ‏نَعْتِرُ ‏ ‏فِي الْجَاهِلِيَّةِ قَالَ ‏ ‏اذْبَحُوا لِلَّهِ تَبَارَكَ وَتَعَالَى فِي أَيِّ شَهْرٍ مَا كَانَ وَبَرُّوا اللَّهَ عَزَّ وَجَلَّ وَأَطْعِمُوا ‏","","",""]];
